#[derive(Debug, Clone, PartialEq)]
enum RequestItem {
    DataField { key: String, raw_key: String, value: String },
    DataFieldFromFile { key: String, raw_key: String, file_path: String },
    JsonField { key: String, raw_key: String, json_value: serde_json::Value },
    UrlParam { key: String, value: String },
    UrlParamFromFile { key: String, file_path: String },
    HttpHeader { key: String, value: String },
    HttpHeaderFromFile { key: String, file_path: String },
    HttpHeaderToUnset { key: String },
    FormFile { key: String, file_name: String, file_type: Option<String>, file_name_header: Option<String> },
    BodyFile { file_name: String, file_type: Option<String> },
}

// For escaping
fn unescape_key(s: &str) -> String {
    let mut res = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(next) = chars.next() {
                res.push(next);
            }
        } else {
            res.push(c);
        }
    }
    res
}

fn parse_request_item(item: &str) -> Result<RequestItem, String> {
    // Need to handle escaping for separators. The separators are: "==", ":=", "=", "@", ":", ";"
    // Actually we need to find unescaped separator.
    // Process: iterate through string, looking for unescaped separators, with precedence? In httpie/xh, the order matters: "==" checked before "=", ":=" before ":", etc.
    // Also need to handle "@" at beginning for body file.
    // For header: "header:value", "header:" (unset), "header;" (empty)
    // For file upload: "key@filename" with optional ";type=" and ";filename="
    // For body file: "@filename" with optional type?
    // For data field from file: "key=@filename" means value from file? Actually "key=@file" means value from file? In JSON mode, we saw "foo=@/tmp/key.txt" => DataFieldFromFile.
    // Also "key:=@file"? Not? Let's check: "key:=@file" would be? Possibly json reading from file? In HTTPie, "@/file" can be used to read value from file for any type? For header, "X:@file".
    // For query param, "key==@file"? Possibly.

    // First, handle body file: starts with "@" not containing other separators before? Eg "@filename"
    // Body file is when string starts with "@" and not contain other assignment separators? But it could also have ";type=" suffix.
    // In debug earlier, "@./README.md;type=text/plain" was parsed as BodyFile with type.

    // We'll attempt to parse in order of specificity.

    // Check for body file: if starts with '@'
    if item.starts_with('@') {
        let rest = &item[1..];
        // rest may contain ";type=" or ";filename=" ? The spec says for file upload you can set type/filename, but for body file, type is content-type?
        // Example earlier: "@./README.md;type=text/plain" => file_name "./README.md", file_type Some("text/plain")
        // So parse: filename up to ";", then parse options.
        let (file_name, file_type, file_name_header) = parse_file_spec(rest);
        // body file is FormFile with empty key? In xh debug it was FormFile with key "" for @file.
        // We'll represent as BodyFile.
        return Ok(RequestItem::BodyFile { file_name, file_type });
    }

    // For other types, we need to find separator.
    // We'll scan for unescaped separators, but need to differentiate.
    // Potential separators in order of length: "==", ":=", "=", "@", ":", ";"
    // However ":" and ";" for headers need special handling: header is "key:value", "key:" unset, "key;" empty.
    // For data field, "=" and ":=".
    // For file upload, "@".
    // For url param, "==".
    // Also for file value from file: "key=@file" contains "=@", which is "=" plus "@". How to detect? The pattern "key=@file" should be DataFieldFromFile, not DataField with value "@file".
    // In our earlier debug, "foo=@/tmp/key.txt" => DataFieldFromFile. So "=" followed by "@" indicates from file.
    // Similarly header from file: "X:@file" => HttpHeaderFromFile.

    // Let's implement scanning: find first unescaped occurrence of each separator, but with priority.

    // Helper to find unescaped substring.
    fn find_unescaped(s: &str, pat: &str) -> Option<usize> {
        let mut idx = 0;
        let chars: Vec<char> = s.chars().collect();
        let pat_chars: Vec<char> = pat.chars().collect();
        if pat_chars.len() == 0 { return None; }
        let mut i = 0;
        while i + pat_chars.len() <= chars.len() {
            if chars[i] == '\\' {
                // skip escaped char
                i += 2;
                continue;
            }
            // check if substring matches at i
            let mut matches = true;
            for j in 0..pat_chars.len() {
                if chars[i+j] != pat_chars[j] {
                    matches = false;
                    break;
                }
            }
            if matches {
                // also ensure not escaped before
                // we already skipped escaped, but need to check if previous char is backslash escaped even though we skipped? The above skipping ensures we skip escaped positions, but if pattern itself contains escaped char, we need more.
                // Simplify: if i>0 and chars[i-1]=='\\', then it's escaped? But we already skip those with backslash skip, so if we are here, previous char not backslash escaping this.
                // However need to handle double escaping? We'll ignore.
                return Some(s.chars().take(i).collect::<String>().len()); // but this length is in chars, need byte index
                // Actually we need byte index. We'll compute byte index via char positions.
            }
            i+=1;
        }
        None
    }

    // More accurate: work on byte string with escaping awareness.
    // We'll write a function that returns byte index of first unescaped occurrence.

    fn find_unescaped_bytes(s: &str, pat: &str) -> Option<usize> {
        let bytes = s.as_bytes();
        let pat_bytes = pat.as_bytes();
        let mut i = 0;
        while i + pat_bytes.len() <= bytes.len() {
            if bytes[i] == b'\\' {
                // skip next byte
                i += 2;
                continue;
            }
            if &bytes[i..i+pat_bytes.len()] == pat_bytes {
                return Some(i);
            }
            i+=1;
        }
        None
    }

    // Now, try to find separators in order: "==", ":=", "=", "@", ":", ";"
    // But we need to be careful: for "key==value", it contains "=" as well, but we should match "==" first.
    // Also for "key:=value", contains ":=".
    // For file upload: "key@file" contains "@".
    // For header: "key:value" contains ":".
    // For header empty: "key;" contains ";".
    // For header unset: "key:" contains ":" with empty value after.

    // We'll first check for "=="
    if let Some(pos) = find_unescaped_bytes(item, "==") {
        let key_part = &item[..pos];
        let value_part = &item[pos+2..];
        let key = unescape_key(key_part);
        // value could be from file? "@"
        if value_part.starts_with('@') {
            // file reading for url param
            let file_path = &value_part[1..];
            return Ok(RequestItem::UrlParamFromFile { key, file_path: file_path.to_string() });
        } else {
            // unescape value? ForUrlParam, value is as is but unescape?
            let value = unescape_key(value_part);
            return Ok(RequestItem::UrlParam { key, value });
        }
    }

    // Check ":="
    if let Some(pos) = find_unescaped_bytes(item, ":=") {
        let key_part = &item[..pos];
        let value_part = &item[pos+2..];
        let raw_key = key_part.to_string();
        let key = unescape_key(key_part);
        // value is JSON literal, but could be from file @?
        if value_part.starts_with('@') {
            // reading JSON from file? Not sure. For now treat as error? But we can read file and parse JSON?
            // In HTTPie, you can use @file for := as well.
            let file_path = &value_part[1..];
            let content = std::fs::read_to_string(file_path).map_err(|e| format!("No such file or directory (os error {})", e.raw_os_error().unwrap_or(2)))?;
            let json_val: serde_json::Value = serde_json::from_str(&content).map_err(|e| format!("{:?}", e))?;
            return Ok(RequestItem::JsonField { key, raw_key, json_value: json_val });
        } else {
            let json_val: serde_json::Value = serde_json::from_str(value_part).map_err(|e| format!("Invalid value for '[REQUEST_ITEM]...': {:?} {}", item, e))?;
            return Ok(RequestItem::JsonField { key, raw_key, json_value: json_val });
        }
    }

    // Check for file upload: need to handle "key@file;type=...;filename=..."
    // The "@" separator for file upload should be after key, not at start, and file part contains filename.
    // But we have also "key=@file" case where "=" then "@". That case we already handle as DataFieldFromFile if we detect "=" before "@".
    // Let's check "=" with "@" value.
    // We'll look for "@" that appears after key, but before any ";"
    // Actually we should look for "=" first, then check if value starts with "@".
    if let Some(eq_pos) = find_unescaped_bytes(item, "=") {
        // Ensure not "==" (already handled) and not ":=" (handled)
        // Check if preceding char is ':'? That would be ":=" already. So we already excluded ":=".
        // Also ensure next char not "=" (that's "==")
        // So this "=" is a data field separator.
        // But also need to differentiate "key@file" which also contains "@" but not "=".
        // For data field, if value starts with "@", it's from file.
        let key_part = &item[..eq_pos];
        let value_part = &item[eq_pos+1..];
        if value_part.starts_with('@') {
            let raw_key = key_part.to_string();
            let key = unescape_key(key_part);
            let file_path = &value_part[1..];
            return Ok(RequestItem::DataFieldFromFile { key, raw_key, file_path: file_path.to_string() });
        } else {
            // check if key contains "@" before "="? That would be weird.
            // For now treat as DataField, but need to ensure not file upload (key@file).
            // File upload detection should be before "=".
            // We'll handle file upload separately below before this.
            // So if we reach here, it's DataField.
            let raw_key = key_part.to_string();
            let key = unescape_key(key_part);
            let value = unescape_key(value_part);
            return Ok(RequestItem::DataField { key, raw_key, value });
        }
    }

    // If we reach here, no "=" found, try file upload "@"
    // File upload syntax: key@filename;type=...;filename=...
    if let Some(at_pos) = find_unescaped_bytes(item, "@") {
        // at_pos >0, not at start (start case already handled)
        let key_part = &item[..at_pos];
        let file_spec = &item[at_pos+1..];
        // file_spec may contain ";type=" and ";filename="
        let (file_name, file_type, file_name_header) = parse_file_spec(file_spec);
        let key = unescape_key(key_part);
        return Ok(RequestItem::FormFile { key, file_name, file_type, file_name_header });
    }

    // Header: ":" 
    // Need to check for ":" that is not ":=" (already checked)
    if let Some(colon_pos) = find_unescaped_bytes(item, ":") {
        let key_part = &item[..colon_pos];
        let value_part = &item[colon_pos+1..];
        let key = unescape_key(key_part);
        if value_part.is_empty() {
            // "header:" => unset
            return Ok(RequestItem::HttpHeaderToUnset { key });
        } else if value_part.starts_with('@') {
            // header from file
            let file_path = &value_part[1..];
            return Ok(RequestItem::HttpHeaderFromFile { key, file_path: file_path.to_string() });
        } else {
            let value = unescape_key(value_part);
            // Trim leading? Keep as is.
            return Ok(RequestItem::HttpHeader { key, value });
        }
    }

    // Header empty value: ";"
    if let Some(semi_pos) = find_unescaped_bytes(item, ";") {
        // If ";" at end => header empty
        // Actually "header;" => key "header", value empty
        // But our parsing above for ":" didn't catch.
        // Check if item ends with ";" and contains no other separators? For "Foo;" we have key "Foo", empty.
        // The spec says "header;" for empty value.
        // So if we find ";" and it's at end of key_part? Let's treat.
        if semi_pos == item.len()-1 {
            let key_part = &item[..semi_pos];
            let key = unescape_key(key_part);
            return Ok(RequestItem::HttpHeader { key, value: "".to_string() });
        }
        // Also could be "header;type=..."? No that's file spec.
        // For now, treat as header empty if ends with ";"
    }

    // Also check for ";" alone at end case: "Foo;" already handled? We checked at_pos for "@" not, ":" not, so ";" detection should catch.
    if item.ends_with(';') {
        let key_part = &item[..item.len()-1];
        let key = unescape_key(key_part);
        return Ok(RequestItem::HttpHeader { key, value: "".to_string() });
    }

    // If nothing matched, invalid
    Err(format!("Invalid value for '[REQUEST_ITEM]...': {:?}", item))
}

fn parse_file_spec(spec: &str) -> (String, Option<String>, Option<String>) {
    // spec like "filename;type=text/plain;filename=custom.txt"
    // Split by ';'
    let mut parts = spec.split(';');
    let file_name = parts.next().unwrap_or("").to_string();
    let mut file_type = None;
    let mut file_name_header = None;
    for part in parts {
        if part.starts_with("type=") {
            file_type = Some(part[5..].to_string());
        } else if part.starts_with("filename=") {
            file_name_header = Some(part[9..].to_string());
        }
    }
    (file_name, file_type, file_name_header)
}

#[derive(Debug)]
struct FormatOptions {
    json_indent: Option<usize>,
    json_format: Option<bool>,
    headers_sort: Option<bool>,
}

fn parse_format_options(opts: &[String]) -> Result<FormatOptions, String> {
    let mut json_indent = None;
    let mut json_format = None;
    let mut headers_sort = None;
    for opt_str in opts {
        for part in opt_str.split(',') {
            if part.trim().is_empty() { continue; }
            let kv: Vec<&str> = part.splitn(2, ':').collect();
            if kv.len() !=2 {
                return Err(format!("Invalid format option {}", part));
            }
            let k = kv[0].trim();
            let v = kv[1].trim();
            match k {
                "json.indent" => {
                    let n: usize = v.parse().map_err(|_| format!("Invalid indent"))?;
                    json_indent = Some(n);
                },
                "json.format" => {
                    match v {
                        "true" => json_format = Some(true),
                        "false" => json_format = Some(false),
                        _ => return Err(format!("Invalid json.format")),
                    }
                },
                "headers.sort" => {
                    match v {
                        "true" => headers_sort = Some(true),
                        "false" => headers_sort = Some(false),
                        _ => return Err(format!("Invalid headers.sort")),
                    }
                },
                _ => return Err(format!("Unknown format option {}", k)),
            }
        }
    }
    Ok(FormatOptions { json_indent, json_format, headers_sort })
}

fn is_method_token(s: &str) -> bool {
    // Only ASCII letters
    !s.is_empty() && s.chars().all(|c| c.is_ascii_alphabetic())
}

fn is_url_like(s: &str) -> bool {
    // For single arg when no method, what is considered URL?
    // We need to approximate.
    // If contains "://", true
    // If starts with ":", true (for :8000, :/path)
    // If contains "/", true
    // If contains "@", true (for @file? but that's request item)
    // If contains ";" true?
    // If contains ".", true
    // If contains "="? The earlier test showed "foo=bar" considered URL when alone.
    // If contains "==", true
    // If contains ":", but need to handle invalid port? We'll just say if contains ":" and second part maybe numeric? For simplicity, if contains ":", true but later validation for port.
    // If contains ":" -> might be URL, but we need to check invalid port later.
    // For simplicity, if string contains any of "://", "/", "@", ";", ".", "=", ":", true, else false.
    // But "foo" fails, "example" fails, both have no such chars.
    // "localhost" fails, "example.com" succeeds because dot.
    // So this heuristic works.
    if s.contains("://") { return true; }
    if s.starts_with(':') { return true; }
    if s.contains('/') { return true; }
    if s.contains('@') { return true; }
    if s.contains('.') { return true; }
    if s.contains(';') { return true; }
    if s.contains('=') { return true; }
    if s.contains(':') { return true; } // includes port
    // Also IP?
    false
}

fn is_url_like_for_second(s: &str) -> bool {
