fn parse_url(input: &str, default_scheme: &str) -> Result<url::Url, String> {
    // Handle shorthand:
    // ":8000" => "http://localhost:8000/"
    // ":/path" => "http://localhost/path"
    // "://example.com" => "http://example.com"
    // "example.com" => "http://example.com"
    // "example.com/path" => "http://example.com/path"
    // "localhost:8000" => "http://localhost:8000"
    // "http://example.com" => as is
    // Also need to handle "example.com?query" etc.

    let mut url_str = input.to_string();

    // If starts with "://", prepend default scheme + "://"? Actually "://example.com" => "http://example.com"
    if url_str.starts_with("://") {
        url_str = format!("{}://{}", if default_scheme.is_empty() { "http" } else { default_scheme }, &url_str[3..]);
        // But also need to handle "://example.com/path"
    } else if url_str.starts_with(':') {
        // Could be ":8000" or ":/path"
        if url_str.starts_with("://") {
            // already handled
        } else {
            // ":8000" or ":8000/path" or ":/path"
            // According to spec: ":8000" => "localhost:8000", ":/path" => "localhost/path"
            // So prepend "localhost" after colon? Actually ":8000" => "localhost:8000"
            // Implementation: if second char is '/', then ": /path" => "localhost/path"
            // else ":8000" => "localhost:8000"
            // So we can transform ":8000" => "http://localhost:8000" and ":/path" => "http://localhost/path"
            if url_str.len() >= 2 && url_str.chars().nth(1) == Some('/') {
                // ":/path"
                url_str = format!("{}://localhost{}", if default_scheme.is_empty() { "http" } else { default_scheme }, &url_str[1..]);
            } else {
                // ":8000" or ":8000/path"
                // Find slash after port
                if let Some(slash_idx) = url_str.find('/') {
                    let port_part = &url_str[..slash_idx];
                    let path_part = &url_str[slash_idx..];
                    // port_part like ":8000"
                    url_str = format!("{}://localhost{}{}", if default_scheme.is_empty() { "http" } else { default_scheme }, port_part, path_part);
                } else {
                    url_str = format!("{}://localhost{}", if default_scheme.is_empty() { "http" } else { default_scheme }, url_str);
                }
            }
        }
    } else if !url_str.contains("://") {
        // No scheme
        // If contains "://"? already handled
        // If like "example.com", "example.com/path", "localhost:8000", etc, prepend default_scheme
        // But need to handle if it looks like "example.com:8000/path"
        // Prepend scheme://
        url_str = format!("{}://{}", if default_scheme.is_empty() { "http" } else { default_scheme }, url_str);
    }

    // Now parse with url crate
    let parsed = url::Url::parse(&url_str).map_err(|e| format!("Invalid <URL>: {}", e))?;

    // Validate port if present? url crate already validates port numeric.
    // But original error message for invalid port is "invalid port number", not url crate message. We'll map.

    Ok(parsed)
}

