fn build_json_from_data(fields: Vec<(String, serde_json::Value)>) -> serde_json::Value {
    // fields have raw_key like "a[b][c]" and value as string or json value already?
    // For DataField, value is string.
    // For JsonField, value is json.
    // Need to construct nested JSON.

    let mut root = serde_json::Value::Object(serde_json::Map::new());

    for (raw_key, val) in fields {
        // Parse raw_key as path: e.g., "a[b][c]" or "a[0]" or "a[]"
        // We'll parse using state machine.
        let mut path_parts: Vec<PathPart> = Vec::new();
        // First part before any '['
        let mut current = String::new();
        let mut chars = raw_key.chars().peekable();
        while let Some(&c) = chars.peek() {
            if c == '[' {
                if !current.is_empty() {
                    path_parts.push(PathPart::Key(current.clone()));
                    current.clear();
                }
                // consume '['
                chars.next();
                // read until ']'
                let mut inner = String::new();
                while let Some(ch) = chars.next() {
                    if ch == ']' {
                        break;
                    } else {
                        inner.push(ch);
                    }
                }
                if inner.is_empty() {
                    path_parts.push(PathPart::Append);
                } else if let Ok(idx) = inner.parse::<usize>() {
                    path_parts.push(PathPart::Index(idx));
                } else {
                    path_parts.push(PathPart::Key(inner));
                }
            } else {
                current.push(c);
                chars.next();
            }
        }
        if !current.is_empty() {
            path_parts.push(PathPart::Key(current));
        }

        // Now insert into root
        insert_path(&mut root, &path_parts, val);
    }

    root
}

#[derive(Debug, Clone)]
enum PathPart {
    Key(String),
    Index(usize),
    Append,
}

fn insert_path(root: &mut serde_json::Value, path: &[PathPart], value: serde_json::Value) {
    if path.is_empty() {
        *root = value;
        return;
    }

    let mut cur = root;
    for (i, part) in path.iter().enumerate() {
        let is_last = i == path.len() - 1;
        match part {
            PathPart::Key(k) => {
                if is_last {
                    if let serde_json::Value::Object(map) = cur {
                        map.insert(k.clone(), value.clone());
                    } else {
                        // if cur is not object, override?
                        *cur = serde_json::Value::Object({
                            let mut m = serde_json::Map::new();
                            m.insert(k.clone(), value.clone());
                            m
                        });
                    }
                    break;
                } else {
                    // intermediate: ensure object or array?
                    // Look ahead: next part is Index or Append => need array, else object
                    let next_is_array = matches!(path.get(i+1), Some(PathPart::Index(_)) | Some(PathPart::Append));
                    if let serde_json::Value::Object(map) = cur {
                        if !map.contains_key(k) {
                            if next_is_array {
                                map.insert(k.clone(), serde_json::Value::Array(vec![]));
                            } else {
                                map.insert(k.clone(), serde_json::Value::Object(serde_json::Map::new()));
                            }
                        }
                        cur = map.get_mut(k).unwrap();
                    } else {
                        // cur is not object, replace?
                        *cur = serde_json::Value::Object(serde_json::Map::new());
                        if let serde_json::Value::Object(map) = cur {
                            if next_is_array {
                                map.insert(k.clone(), serde_json::Value::Array(vec![]));
                            } else {
                                map.insert(k.clone(), serde_json::Value::Object(serde_json::Map::new()));
                            }
                            cur = map.get_mut(k).unwrap();
                        }
                    }
                }
            },
            PathPart::Index(idx) => {
                if is_last {
                    if let serde_json::Value::Array(arr) = cur {
                        // ensure length
                        while arr.len() <= *idx {
                            arr.push(serde_json::Value::Null);
                        }
                        arr[*idx] = value.clone();
                    } else {
                        // if cur is Null, create array
                        *cur = serde_json::Value::Array(vec![]);
                        if let serde_json::Value::Array(arr) = cur {
                            while arr.len() <= *idx {
                                arr.push(serde_json::Value::Null);
                            }
                            arr[*idx] = value.clone();
                        }
                    }
                    break;
                } else {
                    // intermediate array index
                    if let serde_json::Value::Array(arr) = cur {
                        while arr.len() <= *idx {
                            arr.push(serde_json::Value::Null);
                        }
                        // ensure that element is object/array for next
                        let next_is_array = matches!(path.get(i+1), Some(PathPart::Index(_)) | Some(PathPart::Append));
                        if arr[*idx].is_null() {
                            if next_is_array {
                                arr[*idx] = serde_json::Value::Array(vec![]);
                            } else {
                                arr[*idx] = serde_json::Value::Object(serde_json::Map::new());
                            }
                        }
                        cur = &mut arr[*idx];
                    } else {
                        // cur not array, make it array
                        *cur = serde_json::Value::Array(vec![]);
                        if let serde_json::Value::Array(arr) = cur {
                            while arr.len() <= *idx {
                                arr.push(serde_json::Value::Null);
                            }
                            let next_is_array = matches!(path.get(i+1), Some(PathPart::Index(_)) | Some(PathPart::Append));
                            if next_is_array {
                                arr[*idx] = serde_json::Value::Array(vec![]);
                            } else {
                                arr[*idx] = serde_json::Value::Object(serde_json::Map::new());
                            }
                            cur = &mut arr[*idx];
                        }
                    }
                }
            },
            PathPart::Append => {
                if is_last {
                    if let serde_json::Value::Array(arr) = cur {
                        arr.push(value.clone());
                    } else {
                        // if cur is Null or not array, make array and push
                        // But if cur was previously array of same key, handled earlier.
                        // If cur is not array, we need to handle: for "a[]=1" where a is not yet array, cur is array already from previous key handling? Actually for "a[]=1", path is [Key("a"), Append]. The first part Key("a") creates array at root["a"], then cur points to that array, then Append pushes.
                        // So if cur is array, push.
                        // If cur is not array, make array?
                        *cur = serde_json::Value::Array(vec![value.clone()]);
                    }
                    break;
                } else {
                    // intermediate append: need to push new element and then descend
                    let next_is_array = matches!(path.get(i+1), Some(PathPart::Index(_)) | Some(PathPart::Append));
                    if let serde_json::Value::Array(arr) = cur {
                        // push new container
                        if next_is_array {
                            arr.push(serde_json::Value::Array(vec![]));
                        } else {
                            arr.push(serde_json::Value::Object(serde_json::Map::new()));
                        }
                        let len = arr.len();
                        cur = &mut arr[len-1];
                    } else {
                        *cur = serde_json::Value::Array(vec![]);
                        if let serde_json::Value::Array(arr) = cur {
                            if next_is_array {
                                arr.push(serde_json::Value::Array(vec![]));
                            } else {
                                arr.push(serde_json::Value::Object(serde_json::Map::new()));
                            }
                            let len = arr.len();
                            cur = &mut arr[len-1];
                        }
                    }
                }
            },
        }
    }
}

