        // We'll build based on body_type and items.

        // First, handle auth
        if let Some(auth) = cli.auth.clone() {
            let auth_type = cli.auth_type.clone().unwrap_or_else(|| "basic".to_string());
            match auth_type.as_str() {
                "basic" => {
                    if cli.curl_long {
                        curl_parts.push("--basic".to_string());
                        curl_parts.push("--user".to_string());
                    } else {
                        curl_parts.push("--basic".to_string());
                        curl_parts.push("-u".to_string());
                    }
                    curl_parts.push(format!("{}:{}", auth.split(':').next().unwrap_or(""), auth.split(':').skip(1).collect::<Vec<_>>().join(":")));
                },
                "digest" => {
                    if cli.curl_long {
                        curl_parts.push("--digest".to_string());
                        curl_parts.push("--user".to_string());
                    } else {
                        curl_parts.push("--digest".to_string());
                        curl_parts.push("-u".to_string());
                    }
                    curl_parts.push(auth.clone());
                },
                "bearer" => {
                    if cli.curl_long {
                        curl_parts.push("--oauth2-bearer".to_string());
                    } else {
                        curl_parts.push("--oauth2-bearer".to_string());
                    }
                    curl_parts.push(auth.clone());
                },
                _ => {}
            }
        } else if let Some(bearer) = cli.bearer.clone() {
            if cli.curl_long {
                curl_parts.push("--oauth2-bearer".to_string());
            } else {
                curl_parts.push("--oauth2-bearer".to_string());
            }
            curl_parts.push(bearer.clone());
        }

        // Handle verify no => -k
        if let Some(v) = cli.verify.clone() {
            if v=="no" || v=="false" {
                if cli.curl_long {
                    curl_parts.push("--insecure".to_string());
                } else {
                    curl_parts.push("-k".to_string());
                }
            }
        }

        // Handle custom headers (excluding auth, host, content-length, etc that curl sets automatically?)
        // For json, original added content-type and accept headers via -H.
        // So we should add all headers that are not Host and not Content-Length and not Connection and not Accept-Encoding and not User-Agent? Actually original curl command included content-type and accept, but not User-Agent, Accept-Encoding, Connection, Host.
        // Let's see examples: curl http://example.com/ -H 'content-type: application/json' -H 'accept: ...' – it did NOT include User-Agent, Accept-Encoding, Host, etc.
        // For header custom "X:1", it included -H 'x: 1' or --header 'x: 1' when long.
        // So we should include custom headers and content-type and accept if they are not default auto?

        // We'll add Content-Type and Accept if present and not host etc.
        // For simplicity, gather all headers that are content-type or accept or custom.

        let mut curl_headers: Vec<(String,String)> = Vec::new();
        if let Some(ct) = content_type.clone() {
            if !has_content_type_custom {
                // content-type from body, add
                curl_headers.push(("content-type".to_string(), ct));
            }
        }
        // If has custom content-type, it will be in custom_headers, but we already filtered? Actually has_content_type_custom means custom provided, but we still should include it if provided.
        // For accept header:
        if !has_accept_custom {
            // accept from our headers
            for (k,v) in &headers {
                if k.to_lowercase()=="accept" {
                    curl_headers.push((k.to_lowercase(), v.clone()));
                }
            }
        }
        // Add custom headers (excluding some)
        for (k,v) in &headers {
            let kl = k.to_lowercase();
            if kl=="host" || kl=="content-length" || kl=="connection" || kl=="accept-encoding" || kl=="user-agent" {
                continue;
            }
            if kl=="accept" || kl=="content-type" {
                // already handled? But if custom, include
                if has_content_type_custom || has_accept_custom {
                    // include if not already
                    if !curl_headers.iter().any(|(hk,_)| hk.to_lowercase()==kl) {
                        curl_headers.push((k.clone(), v.clone()));
                    } else {
                        // if custom content-type provided, replace
                        if kl=="content-type" && has_content_type_custom {
                            // find custom
                            curl_headers.retain(|(hk,_)| hk.to_lowercase()!="content-type");
                            curl_headers.push((k.clone(), v.clone()));
                        }
                        if kl=="accept" && has_accept_custom {
                            curl_headers.retain(|(hk,_)| hk.to_lowercase()!="accept");
                            curl_headers.push((k.clone(), v.clone()));
                        }
                    }
                }
                continue;
            }
            // custom header
            curl_headers.push((k.clone(), v.clone()));
        }

        // Actually we need to include custom headers that were part of original custom_headers, not all headers.
        // Let's instead directly use custom_headers plus content-type and accept.

        // Rebuild curl_headers from scratch: content-type, accept, custom
        let mut final_curl_headers: Vec<(String,String)> = Vec::new();
        // content-type
        if let Some(ct) = content_type {
            // if custom content-type exists, use custom value (which is in headers)
            // Find in headers if content-type present
            if let Some((_,v)) = headers.iter().find(|(k,_)| k.to_lowercase()=="content-type") {
                final_curl_headers.push(("content-type".to_string(), v.clone()));
            } else {
                final_curl_headers.push(("content-type".to_string(), ct));
            }
        } else {
            if has_content_type_custom {
                if let Some((_,v)) = headers.iter().find(|(k,_)| k.to_lowercase()=="content-type") {
                    final_curl_headers.push(("content-type".to_string(), v.clone()));
                }
            }
        }
        // accept
        if let Some((_,v)) = headers.iter().find(|(k,_)| k.to_lowercase()=="accept") {
            // For form, accept is */* which curl doesn't need? But original for form didn't include accept.
            // In earlier examples, form didn't have accept header in curl.
            // For json, it did have accept.
            // So we should include accept only if it's not */*? Or include always for json?
            // Let's include if not */*? Actually earlier for GET, curl had no accept header. For GET with Accept */*, curl had no -H.
            // For POST json, it had accept header.
            // So include accept if it's not */*?
            if v!="*/*" {
                final_curl_headers.push(("accept".to_string(), v.clone()));
            }
        }
        // custom headers
        for (k,v) in custom_headers {
            final_curl_headers.push((k.clone(), v.clone()));
        }

        for (k,v) in final_curl_headers {
            // Format header for curl: "k: v" ? Original used "x: 1" with space after colon for header, but for content-type used "content-type: application/json" without space? Actually example had 'content-type: application/json' with space.
            // For custom header "X:1", original curl showed "-H 'x: 1'" with space? Let's check: earlier curl with X:1 gave "-H 'x: 1'" (lowercase key, space).
            // So format as "k: v" with space? But for content-type, they used "content-type: application/json" (space after colon).
            // We'll format as "k: v" if value non-empty, else "k:"? For empty value, "X: "?

            let header_str = if v.is_empty() {
                format!("{}:", k)
            } else {
                format!("{}: {}", k, v)
            };

            // Quote header value for shell: use single quotes, escape single quotes.
            let quoted = if header_str.contains('\'') {
                let esc = header_str.replace('\'', "'\\''");
                format!("'{}'", esc)
            } else {
                format!("'{}'", header_str)
            };

            if cli.curl_long {
                curl_parts.push("--header".to_string());
            } else {
                curl_parts.push("-H".to_string());
            }
            curl_parts.push(quoted);
        }

        // Body for curl
        if let Some(ref body) = body_string {
            if is_multipart {
                // multipart already handled? For multipart, we need -F for each field
                // Our body_string for multipart is the raw multipart body, but curl translation uses -F.
                // So we should not use body_string for curl multipart, but generate -F parts.

                // Remove previous content-type header if it was multipart? Original curl for multipart didn't include content-type header, it used -F which sets it automatically.
                // So we should remove content-type header from curl_parts if multipart?
                // Actually we added content-type header for multipart earlier, but original didn't. Let's check: For multipart forced, curl was "curl http://example.com/ -F 'foo=bar'" without content-type.
                // So for multipart, we should not include content-type header.

                // We'll filter out content-type header from curl_parts if multipart.
                curl_parts.retain(|p| !p.contains("multipart") && !p.contains("content-type"));

                // Now generate -F fields
                for it in &items {
                    match it {
                        RequestItem::DataField{key,value,..} => {
                            let field = format!("{}={}", key, value);
                            let quoted = shell_quote(&field);
                            if cli.curl_long {
                                curl_parts.push("--form".to_string());
                            } else {
                                curl_parts.push("-F".to_string());
                            }
                            curl_parts.push(quoted);
                        },
                        RequestItem::FormFile{key,file_name,file_type,file_name_header} => {
                            // -F 'key=@file' or with type/filename?
                            // Original: -F 'foo=@./README.md' (without type)
                            // With type: ?
                            // Example we saw: curl with file upload gave -F 'foo=@./README.md'
                            // For type and filename, spec: "pfp@ra.jpg;type=image/jpeg;filename=profile.jpg" – how curl translates?
                            // Likely -F 'pfp=@ra.jpg;type=image/jpeg;filename=profile.jpg'
                            // So we should reconstruct similar.
                            let mut spec = format!("{}=@{}", key, file_name);
                            if let Some(t) = file_type {
                                spec.push_str(&format!(";type={}", t));
                            }
                            if let Some(fn_) = file_name_header {
                                spec.push_str(&format!(";filename={}", fn_));
                            }
                            let quoted = shell_quote(&spec);
                            if cli.curl_long {
                                curl_parts.push("--form".to_string());
                            } else {
                                curl_parts.push("-F".to_string());
                            }
                            curl_parts.push(quoted);
                        },
                        _ => {}
                    }
                }

            } else if body_type=="form" && !is_multipart {
                // urlencoded: --data-urlencode
                // For each pair, add --data-urlencode 'key=value'
                for it in &items {
                    match it {
                        RequestItem::DataField{key,value,..} => {
                            let field = format!("{}={}", key, value);
                            let quoted = shell_quote(&field);
                            if cli.curl_long {
                                curl_parts.push("--data-urlencode".to_string());
                            } else {
                                curl_parts.push("--data-urlencode".to_string());
                            }
                            curl_parts.push(quoted);
                        },
                        RequestItem::DataFieldFromFile{key,file_path,..} => {
                            let content = std::fs::read_to_string(file_path).unwrap_or_default();
                            let field = format!("{}={}", key, content.trim_end());
                            let quoted = shell_quote(&field);
                            curl_parts.push("--data-urlencode".to_string());
                            curl_parts.push(quoted);
                        },
                        _ => {}
                    }
                }
            } else if has_body_file {
                // @file body: --data-binary @file
                // Find file name
                for it in &items {
                    if let RequestItem::BodyFile{file_name,..} = it {
                        let arg = format!("@{}", file_name);
                        let quoted = if cli.curl_long {
                            // --data-binary
                            arg
                        } else {
                            arg
                        };
                        if cli.curl_long {
                            curl_parts.push("--data-binary".to_string());
                        } else {
                            curl_parts.push("--data-binary".to_string());
                        }
                        curl_parts.push(quoted);
                    }
                    if let RequestItem::FormFile{key,file_name,..} = it {
                        if key.is_empty() {
                            let arg = format!("@{}", file_name);
                            if cli.curl_long {
                                curl_parts.push("--data-binary".to_string());
                            } else {
                                curl_parts.push("--data-binary".to_string());
                            }
                            curl_parts.push(arg);
                        }
                    }
                }
            } else {
                // json or raw
                // -d 'body'
                // For curl, body should be quoted
                let quoted_body = shell_quote(body);
                if cli.curl_long {
                    curl_parts.push("--data".to_string());
                } else {
                    curl_parts.push("-d".to_string());
                }
                curl_parts.push(quoted_body);
            }
        }

        // Output curl command
        println!("{}", curl_parts.join(" "));
        std::process::exit(0);
    }

    // If not curl, handle offline
    if cli.offline {
        // Print request

        // For pretty handling: if pretty is all or colors, add colors
        // For simplicity, we will implement only none and format (without colors) for now, plus all with colors? Let's attempt colors.

        // We'll generate request string
        let mut output = String::new();

        // Request line: METHOD path?query HTTP/1.1
        let path = final_url.path();
        let query = final_url.query().map(|q| format!("?{}", q)).unwrap_or_default();
        let request_line = format!("{} {}{} HTTP/1.1", final_method, path, query);

        // For print options, we have H and B etc. But for offline we only care request.

        if print_str.contains('H') {
            // Print headers
            // For colors, wrap with ANSI?
            // Let's check original's colored output: For pretty=all, request line had colors: \x1b[32mPOST\x1b[0m etc.
            // We need to implement coloring for all and colors.

            let is_color = pretty=="all" || pretty=="colors";

            if is_color {
                // Color mapping from original: method in green, path in cyan with underline? Let's inspect earlier colored output:
                // "POST / HTTP/1.1" colored: \x1b[32mPOST\x1b[0m \x1b[4m\x1b[36m/\x1b[0m \x1b[34mHTTP\x1b[0m/\x1b[34m1.1\x1b[0m
                // So method green, path cyan underlined, HTTP blue, version blue.
                // For headers: header name cyan, value default.

                let colored_line = format!("\x1b[0m\x1b[32m{}\x1b[0m \x1b[0m\x1b[4m\x1b[36m{}\x1b[0m \x1b[0m\x1b[34mHTTP\x1b[0m/\x1b[0m\x1b[34m1.1\x1b[0m", final_method, format!("{}{}", path, query));
                output.push_str(&colored_line);
                output.push_str("\n");
                for (k,v) in &headers {
                    output.push_str(&format!("\x1b[0m\x1b[36m{}\x1b[0m:\x1b[0m \x1b[0m{}\x1b[0m\n", k, v));
