fn generate_boundary() -> String {
    // Generate random boundary similar to original: seems like hex strings separated by '-'
    // Example: "c9060eff36445507-1adcc975c57a1635-ea23bb0d22ea7ec4-89d0573fa7837a6d"
    // That's 4 parts each 16 hex? Actually first part 16, others? Let's count: c9060eff36445507 (16), 1adcc975c57a1635 (16), ea23bb0d22ea7ec4 (16), 89d0573fa7837a6d (16) => 4*16 with dashes.
    // We'll generate 4 random u64 hex.

    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};
    use std::time::{SystemTime, UNIX_EPOCH};

    let mut hasher = DefaultHasher::new();
    SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos().hash(&mut hasher);
    std::process::id().hash(&mut hasher);
    let h = hasher.finish();

    // Use simple pseudo-random
    let mut rng = h;
    let mut parts = Vec::new();
    for _ in 0..4 {
        rng = rng.wrapping_mul(6364136223846793005).wrapping_add(1);
        parts.push(format!("{:016x}", rng));
    }
    parts.join("-")
}

fn shell_quote(s: &str) -> String {
    // Quote for shell: if contains special chars, use single quotes, escape ' as '\''.
    // If contains no spaces or special, may still need quotes? Original uses single quotes for most.
    // We'll always use single quotes and escape.
    if s.is_empty() {
        return "''".to_string();
    }
    // If contains single quote, escape
    if s.contains('\'') {
        // Replace ' with '\'' (end quote, escaped quote, start quote)
        let escaped = s.replace('\'', "'\\''");
        format!("'{}'", escaped)
    } else {
        // Use single quotes
        format!("'{}'", s)
    }
}

