    // For data field, "=" and ":=".
    // For file upload, "@".
    // For url param, "==".
    // Also for file value from file: "key=@file" contains "=@", which is "=" plus "@". How to detect? The pattern "key=@file" should be DataFieldFromFile, not DataField with value "@file".
    // In our earlier debug, "foo=@/tmp/key.txt" => DataFieldFromFile. So "=" followed by "@" indicates from file.
    // Similarly header from file: "X:@file" => HttpHeaderFromFile.

    // Let's implement scanning: find first unescaped occurrence of each separator, but with priority.

    // Helper to find unescaped substring.
    fn find_unescaped(s: &str, pat: &str) -> Option<usize> {
        let mut idx = 0;
        let chars: Vec<char> = s.chars().collect();
        let pat_chars: Vec<char> = pat.chars().collect();
        if pat_chars.len() == 0 { return None; }
        let mut i = 0;
        while i + pat_chars.len() <= chars.len() {
            if chars[i] == '\\' {
                // skip escaped char
                i += 2;
                continue;
            }
            // check if substring matches at i
            let mut matches = true;
            for j in 0..pat_chars.len() {
                if chars[i+j] != pat_chars[j] {
                    matches = false;
                    break;
                }
            }
            if matches {
                // also ensure not escaped before
                // we already skipped escaped, but need to check if previous char is backslash escaped even though we skipped? The above skipping ensures we skip escaped positions, but if pattern itself contains escaped char, we need more.
                // Simplify: if i>0 and chars[i-1]=='\\', then it's escaped? But we already skip those with backslash skip, so if we are here, previous char not backslash escaping this.
                // However need to handle double escaping? We'll ignore.
                return Some(s.chars().take(i).collect::<String>().len()); // but this length is in chars, need byte index
                // Actually we need byte index. We'll compute byte index via char positions.
            }
            i+=1;
        }
        None
    }

    // More accurate: work on byte string with escaping awareness.
    // We'll write a function that returns byte index of first unescaped occurrence.

    fn find_unescaped_bytes(s: &str, pat: &str) -> Option<usize> {
        let bytes = s.as_bytes();
        let pat_bytes = pat.as_bytes();
        let mut i = 0;
        while i + pat_bytes.len() <= bytes.len() {
            if bytes[i] == b'\\' {
                // skip next byte
                i += 2;
                continue;
            }
            if &bytes[i..i+pat_bytes.len()] == pat_bytes {
                return Some(i);
            }
            i+=1;
        }
        None
    }

    // Now, try to find separators in order: "==", ":=", "=", "@", ":", ";"
    // But we need to be careful: for "key==value", it contains "=" as well, but we should match "==" first.
    // Also for "key:=value", contains ":=".
    // For file upload: "key@file" contains "@".
