            return Ok(RequestItem::JsonField { key, raw_key, json_value: json_val });
        } else {
            let json_val: serde_json::Value = serde_json::from_str(value_part).map_err(|e| format!("Invalid value for '[REQUEST_ITEM]...': {:?} {}", item, e))?;
