fn is_url_like(s: &str) -> bool {
    // For single arg when no method, what is considered URL?
    // We need to approximate.
    // If contains "://", true
    // If starts with ":", true (for :8000, :/path)
    // If contains "/", true
    // If contains "@", true (for @file? but that's request item)
    // If contains ";" true?
    // If contains ".", true
    // If contains "="? The earlier test showed "foo=bar" considered URL when alone.
    // If contains "==", true
    // If contains ":", but need to handle invalid port? We'll just say if contains ":" and second part maybe numeric? For simplicity, if contains ":", true but later validation for port.
    // If contains ":" -> might be URL, but we need to check invalid port later.
    // For simplicity, if string contains any of "://", "/", "@", ";", ".", "=", ":", true, else false.
    // But "foo" fails, "example" fails, both have no such chars.
    // "localhost" fails, "example.com" succeeds because dot.
    // So this heuristic works.
    if s.contains("://") { return true; }
    if s.starts_with(':') { return true; }
    if s.contains('/') { return true; }
    if s.contains('@') { return true; }
    if s.contains('.') { return true; }
    if s.contains(';') { return true; }
    if s.contains('=') { return true; }
    if s.contains(':') { return true; } // includes port
    // Also IP?
    false
}

fn is_url_like_for_second(s: &str) -> bool {
    // For second arg when method present, allow single label like "foo"
    // So any non-empty string that is not invalid request item? Actually we allow almost anything except it fails invalid port check.
    // We'll say if it contains invalid port (colon + non-numeric and not slash), then false? But we need to detect invalid port error.
    // For simplicity, if string contains ":" then we need to check if after colon it's numeric or empty or starts with "/"?
    // Original error for "foo:bar" invalid port: so "foo:bar" should be considered URL attempt but fails with invalid port error, not missing.
    // So for second arg, we should attempt to parse as URL and if fails due to port, return error Invalid <URL>.
    // For our detection, we can say if string contains ":" and after colon not numeric and not empty and not "/", then it's invalid URL but still considered URL attempt.
    // For method detection, we want second arg to be considered URL if it could be URL (including single label).
    // So for second arg, we can say: if string is non-empty and not containing request item separators "==", ":=", "=", "@" maybe? But earlier "GET foo=bar" considered URL even with "=".
    // So second arg URL is very permissive: any string except maybe containing "=="? But "GET foo==bar" also URL.
    // So we can just return true for any non-empty string, except we need to handle invalid port? That still counts as URL attempt.
    !s.is_empty()
}

fn parse_url(input: &str, default_scheme: &str) -> Result<url::Url, String> {
    // Handle shorthand:
    // ":8000" => "http://localhost:8000/"
    // ":/path" => "http://localhost/path"
    // "://example.com" => "http://example.com"
    // "example.com" => "http://example.com"
    // "example.com/path" => "http://example.com/path"
    // "localhost:8000" => "http://localhost:8000"
    // "http://example.com" => as is
    // Also need to handle "example.com?query" etc.

    let mut url_str = input.to_string();

    // If starts with "://", prepend default scheme + "://"? Actually "://example.com" => "http://example.com"
    if url_str.starts_with("://") {
        url_str = format!("{}://{}", if default_scheme.is_empty() { "http" } else { default_scheme }, &url_str[3..]);
        // But also need to handle "://example.com/path"
    } else if url_str.starts_with(':') {
        // Could be ":8000" or ":/path"
        if url_str.starts_with("://") {
            // already handled
        } else {
            // ":8000" or ":8000/path" or ":/path"
            // According to spec: ":8000" => "localhost:8000", ":/path" => "localhost/path"
            // So prepend "localhost" after colon? Actually ":8000" => "localhost:8000"
            // Implementation: if second char is '/', then ": /path" => "localhost/path"
            // else ":8000" => "localhost:8000"
            // So we can transform ":8000" => "http://localhost:8000" and ":/path" => "http://localhost/path"
            if url_str.len() >= 2 && url_str.chars().nth(1) == Some('/') {
                // ":/path"
                url_str = format!("{}://localhost{}", if default_scheme.is_empty() { "http" } else { default_scheme }, &url_str[1..]);
            } else {
                // ":8000" or ":8000/path"
                // Find slash after port
                if let Some(slash_idx) = url_str.find('/') {
                    let port_part = &url_str[..slash_idx];
                    let path_part = &url_str[slash_idx..];
                    // port_part like ":8000"
                    url_str = format!("{}://localhost{}{}", if default_scheme.is_empty() { "http" } else { default_scheme }, port_part, path_part);
                } else {
                    url_str = format!("{}://localhost{}", if default_scheme.is_empty() { "http" } else { default_scheme }, url_str);
                }
            }
        }
    } else if !url_str.contains("://") {
        // No scheme
        // If contains "://"? already handled
        // If like "example.com", "example.com/path", "localhost:8000", etc, prepend default_scheme
        // But need to handle if it looks like "example.com:8000/path"
        // Prepend scheme://
        url_str = format!("{}://{}", if default_scheme.is_empty() { "http" } else { default_scheme }, url_str);
    }

    // Now parse with url crate
    let parsed = url::Url::parse(&url_str).map_err(|e| format!("Invalid <URL>: {}", e))?;

    // Validate port if present? url crate already validates port numeric.
    // But original error message for invalid port is "invalid port number", not url crate message. We'll map.

    Ok(parsed)
}

