fn main() {
    let args_vec: Vec<String> = std::env::args().collect();
    let bin_path = args_vec.get(0).cloned().unwrap_or_else(|| "xh".to_string());
    let bin_name = Path::new(&bin_path).file_name().and_then(|s| s.to_str()).unwrap_or("xh").to_string();

    if args_vec.len()>=2 && args_vec[1]=="help" {
        let mut cmd = Cli::command();
        cmd.build();
        let help = cmd.render_long_help().to_string();
        println!("{}", help);
        std::process::exit(0);
    }

    if args_vec.iter().any(|a| a=="--version" || a=="-V") {
        println!("xh {}", VERSION);
        println!("-native-tls +rustls");
        std::process::exit(0);
    }

    // Handle negations
    let mut filtered_args = Vec::new();
    filtered_args.push(args_vec[0].clone());
    let mut negations: Vec<String> = Vec::new();
    let mut i=1;
    while i<args_vec.len() {
        let a=&args_vec[i];
        if a.starts_with("--no-") {
            negations.push(a.trim_start_matches("--no-").to_string());
            i+=1;
        } else {
            filtered_args.push(a.clone());
            i+=1;
        }
    }

    let cli = match Cli::try_parse_from(filtered_args) {
        Ok(c) => c,
        Err(e) => {
            e.exit();
        }
    };

    let mut cli = cli;
    for neg in negations {
        match neg.as_str() {
            "json" => cli.json=false,
            "form" => cli.form=false,
            "multipart" => cli.multipart=false,
            "raw" => cli.raw=None,
            "pretty" => cli.pretty=None,
            "format-options" => cli.format_options.clear(),
            "style" => cli.style=None,
            "response-charset" => cli.response_charset=None,
            "response-mime" => cli.response_mime=None,
            "print" => cli.print=None,
            "headers" => cli.headers=false,
            "body" => cli.body=false,
            "meta" => cli.meta=false,
            "verbose" => cli.verbose=0,
            "debug" => cli.debug=false,
            "all" => cli.all=false,
            "history-print" => cli.history_print=None,
            "quiet" => cli.quiet=0,
            "stream" => cli.stream=false,
            "compress" => cli.compress=0,
            "output" => cli.output=None,
            "download" => cli.download=false,
            "continue" => cli.resume=false,
            "session" => cli.session=None,
            "session-read-only" => cli.session_read_only=None,
            "auth-type" => cli.auth_type=None,
            "auth" => cli.auth=None,
            "bearer" => cli.bearer=None,
            "ignore-netrc" => cli.ignore_netrc=false,
            "offline" => cli.offline=false,
            "check-status" => cli.check_status=false,
            "follow" => cli.follow=false,
            "max-redirects" => cli.max_redirects=None,
            "timeout" => cli.timeout=None,
            "proxy" => cli.proxy.clear(),
            "verify" => cli.verify=None,
            "cert" => cli.cert=None,
            "cert-key" => cli.cert_key=None,
            "ssl" => cli.ssl=None,
            "native-tls" => cli.native_tls=false,
            "default-scheme" => cli.default_scheme=None,
            "https" => cli.https=false,
            "http-version" => cli.http_version=None,
            "resolve" => cli.resolve.clear(),
            "interface" => cli.interface=None,
            "ipv4" => cli.ipv4=false,
            "ipv6" => cli.ipv6=false,
            "unix-socket" => cli.unix_socket=None,
            "ignore-stdin" => cli.ignore_stdin=false,
            "curl" => cli.curl=false,
            "curl-long" => cli.curl_long=false,
            "generate" => cli.generate=None,
            "help" => cli.help_flag=false,
            _ => {}
        }
    }

    // generate
    if let Some(gen_kind) = cli.generate.clone() {
        let bin = bin_name.clone();
        match gen_kind.as_str() {
            "complete-bash" => {
                let mut cmd = Cli::command();
