            },
            "complete-zsh" => {
                let mut cmd = Cli::command();
                cmd.set_bin_name(bin.clone());
                let mut buf = Vec::new();
                clap_complete::generate(clap_complete::Shell::Zsh, &mut cmd, bin.clone(), &mut buf);
                println!("{}", String::from_utf8_lossy(&buf));
            },
            "complete-fish" => {
                let mut cmd = Cli::command();
                cmd.set_bin_name(bin.clone());
                let mut buf = Vec::new();
                clap_complete::generate(clap_complete::Shell::Fish, &mut cmd, bin.clone(), &mut buf);
                println!("{}", String::from_utf8_lossy(&buf));
            },
            "complete-elvish" => {
                let mut cmd = Cli::command();
                cmd.set_bin_name(bin.clone());
                let mut buf = Vec::new();
                clap_complete::generate(clap_complete::Shell::Elvish, &mut cmd, bin.clone(), &mut buf);
                println!("{}", String::from_utf8_lossy(&buf));
            },
            "complete-powershell" => {
                let mut cmd = Cli::command();
                cmd.set_bin_name(bin.clone());
                let mut buf = Vec::new();
                clap_complete::generate(clap_complete::Shell::PowerShell, &mut cmd, bin.clone(), &mut buf);
                println!("{}", String::from_utf8_lossy(&buf));
            },
            "complete-nushell" => {
                let tmpl = generate_nushell(&bin);
                println!("{}", tmpl);
            },
            "man" => {
                // For man, try to produce similar to original's man generation
                // Use clap_mangen
                let cmd = Cli::command().bin_name(bin.clone());
                let man = clap_mangen::Man::new(cmd);
                let mut buffer = Vec::new();
                man.render(&mut buffer).unwrap();
                let man_str = String::from_utf8_lossy(&buffer).to_string();
                // Replace placeholders? The template in original is custom, but we will output this
                // To match original binary's date, we need to set date? clap_mangen uses current date? We can post-process .TH line to have our date
                // Let's replace date with "2026-09-08" and version with "0.25.3" to match original binary's output (which we captured)
                // Original .TH line: .TH XH 1 2026-09-08 0.25.3 "User Commands"
                // clap_mangen may generate similar with current date, but we can regex replace
                let mut out = man_str;
                // Replace first line date/version if needed
                // Simple: if out starts with .TH, replace second date occurrence
                // We'll just output as is, but try to make date fixed
                // Use regex to replace date
                // For simplicity, replace any date pattern with 2026-09-08 and version with 0.25.3
                // We'll find .TH line and reconstruct
                let lines: Vec<String> = out.lines().map(|l| l.to_string()).collect();
                let mut new_lines = Vec::new();
                for line in lines {
                    if line.starts_with(".TH") {
                        new_lines.push(format!(".TH XH 1 2026-09-08 0.25.3 \"User Commands\""));
                    } else {
                        new_lines.push(line);
                    }
                }
                println!("{}", new_lines.join("\n"));
