    let args_vec: Vec<String> = std::env::args().collect();
    let bin_path = args_vec.get(0).cloned().unwrap_or_else(|| "xh".to_string());
    let bin_name = Path::new(&bin_path).file_name().and_then(|s| s.to_str()).unwrap_or("xh").to_string();

    if args_vec.len()>=2 && args_vec[1]=="help" {
        let mut cmd = Cli::command();
        cmd.build();
        let help = cmd.render_long_help().to_string();
        println!("{}", help);
        std::process::exit(0);
    }

    if args_vec.iter().any(|a| a=="--version" || a=="-V") {
        println!("xh {}", VERSION);
        println!("-native-tls +rustls");
        std::process::exit(0);
    }

    // Handle negations
    let mut filtered_args = Vec::new();
    filtered_args.push(args_vec[0].clone());
    let mut negations: Vec<String> = Vec::new();
    let mut i=1;
    while i<args_vec.len() {
        let a=&args_vec[i];
        if a.starts_with("--no-") {
            negations.push(a.trim_start_matches("--no-").to_string());
            i+=1;
        } else {
            filtered_args.push(a.clone());
            i+=1;
        }
    }

    let cli = match Cli::try_parse_from(filtered_args) {
        Ok(c) => c,
        Err(e) => {
            e.exit();
        }
    };

    let mut cli = cli;
    for neg in negations {
        match neg.as_str() {
            "json" => cli.json=false,
            "form" => cli.form=false,
            "multipart" => cli.multipart=false,
            "raw" => cli.raw=None,
            "pretty" => cli.pretty=None,
