                let mut cmd = build_command(&bin);
                let mut buf = Vec::new();
                clap_complete::generate(clap_complete::Shell::Elvish, &mut cmd, bin.clone(), &mut buf);
                println!("{}", String::from_utf8_lossy(&buf));
            },
            "complete-powershell" => {
                let mut cmd = build_command(&bin);
                let mut buf = Vec::new();
                clap_complete::generate(clap_complete::Shell::PowerShell, &mut cmd, bin.clone(), &mut buf);
                println!("{}", String::from_utf8_lossy(&buf));
            },
            "complete-nushell" => {
                println!("{}", generate_nushell(&bin));
            },
            "man" => {
                let cmd = build_command(&bin);
                let man = clap_mangen::Man::new(cmd);
                let mut buffer = Vec::new();
                man.render(&mut buffer).unwrap();
                let man_str = String::from_utf8_lossy(&buffer).to_string();
                let lines: Vec<String> = man_str.lines().map(|l| l.to_string()).collect();
                let mut new_lines = Vec::new();
                for line in lines {
                    if line.starts_with(".TH") {
                        new_lines.push(format!(".TH XH 1 2026-09-08 0.25.3 \"User Commands\""));
                    } else {
                        new_lines.push(line);
                    }
                }
                println!("{}", new_lines.join("\n"));
            },
            _ => {
                eprintln!("error: invalid value '{}' for '--generate <KIND>'\n  [possible values: complete-bash, complete-elvish, complete-fish, complete-nushell, complete-powershell, complete-zsh, man]\n\nFor more information, try '--help'.", gen_kind);
                std::process::exit(2);
            }
        }
        std::process::exit(0);
    }

    if native_tls {
        eprintln!("{}: error: This binary was built without native-tls support", bin_name);
        std::process::exit(1);
    }

    // build command for later debug etc not needed

    // default scheme
    let mut default_scheme_str = "http".to_string();
    if let Some(ds) = default_scheme.clone() {
        default_scheme_str = ds;
    } else if https {
        default_scheme_str = "https".to_string();
    } else if ["xhs","https","xhttps"].contains(&bin_name.as_str()) {
        default_scheme_str = "https".to_string();
    }

    // positional handling
    let mut all_positional: Vec<String> = Vec::new();
    if let Some(m) = raw_method_or_url.clone() {
        all_positional.push(m);
    }
    all_positional.extend(raw_rest_args.clone());

    if all_positional.is_empty() {
        eprintln!("error: the following required arguments were not provided:\n  <[METHOD] URL>\n\nUsage: {} <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", bin_name);
        std::process::exit(2);
    }

    let mut method: Option<String> = None;
    let mut url_str: Option<String> = None;
    let mut request_item_strs: Vec<String> = Vec::new();

    if all_positional.len()>=2 {
        let first = &all_positional[0];
        let second = &all_positional[1];
        if is_method_token(first) && is_url_like_for_second(second) {
            match parse_url_custom(second, &default_scheme_str) {
                Ok(_) => {
                    method = Some(first.to_uppercase());
                    url_str = Some(second.clone());
                    request_item_strs = all_positional[2..].to_vec();
                },
                Err(e) => {
                    if e.contains("invalid port") {
                        eprintln!("error: {}\n", e);
                        std::process::exit(2);
                    } else {
                        url_str = Some(first.clone());
                        request_item_strs = all_positional[1..].to_vec();
                    }
                }
            }
        } else {
            url_str = Some(first.clone());
            request_item_strs = all_positional[1..].to_vec();
        }
    } else {
        let first = &all_positional[0];
        if is_url_like(first) || is_url_like_for_second(first) {
            match parse_url_custom(first, &default_scheme_str) {
                Ok(_) => {
                    url_str = Some(first.clone());
                },
                Err(e) => {
                    if e.contains("invalid port") || e.contains("Invalid") {
                        eprintln!("error: {}\n", e);
                        std::process::exit(2);
                    } else {
                        eprintln!("error: Missing <URL>\n\nUsage: {} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", bin_name);
                        std::process::exit(2);
                    }
                }
            }
        } else {
            eprintln!("error: Missing <URL>\n\nUsage: {} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", bin_name);
            std::process::exit(2);
        }
    }

    let url_str = url_str.unwrap();
    let parsed_url = match parse_url_custom(&url_str, &default_scheme_str) {
        Ok(u) => u,
        Err(e) => {
            eprintln!("error: {}\n", e);
            std::process::exit(2);
        }
    };

    for proxy_val in &proxy {
        if let Some(colon) = proxy_val.find(':') {
            let protocol = &proxy_val[..colon];
            let url_part = &proxy_val[colon+1..];
            if url::Url::parse(url_part).is_err() {
                eprintln!("error: invalid value '{}' for '--proxy <PROTOCOL:URL>': Invalid proxy URL '{}' for protocol '{}': relative URL without a base\n\nFor more information, try '--help'.", proxy_val, url_part, protocol);
                std::process::exit(2);
            }
        } else {
            eprintln!("error: invalid value '{}' for '--proxy <PROTOCOL:URL>': Invalid proxy URL '' for protocol '{}': relative URL without a base\n\nFor more information, try '--help'.", proxy_val, proxy_val);
            std::process::exit(2);
        }
    }

    // request items
    let mut items: Vec<RequestItem> = Vec::new();
    for s in request_item_strs {
        match parse_request_item(&s) {
            Ok(it) => items.push(it),
            Err(e) => {
                eprintln!("error: {}\n\nUsage: {} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", e, bin_name);
                std::process::exit(2);
            }
        }
    }

    // body type order
    let mut body_type = "json".to_string();
    {
        let raw_all: Vec<String> = std::env::args().collect();
        for arg in raw_all {
            if arg=="--json" || arg=="-j" {
                body_type="json".to_string();
            } else if arg=="--form" || arg=="-f" {
                body_type="form".to_string();
            } else if arg=="--multipart" {
                body_type="multipart".to_string();
            }
        }
    }

    let mut has_data_fields = false;
    let mut has_form_files = false;
    let mut has_body_file = false;
    for it in &items {
        match it {
            RequestItem::DataField{..} | RequestItem::DataFieldFromFile{..} | RequestItem::JsonField{..} => has_data_fields=true,
            RequestItem::FormFile{key,..} => {
                if key.is_empty() { has_body_file=true; } else { has_form_files=true; }
            },
            RequestItem::BodyFile{..} => has_body_file=true,
            _ => {}
        }
    }

    if raw.is_some() {
        if has_data_fields || has_form_files {
            eprintln!("error: Request body (from --raw) and request data (key=value) cannot be mixed.\n\nUsage: {} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", bin_name);
            std::process::exit(2);
        }
        if has_body_file {
            eprintln!("error: Request body (from --raw) and request data (key=value) cannot be mixed.\n\nUsage: {} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", bin_name);
            std::process::exit(2);
        }
    }

    if has_body_file && (has_data_fields || has_form_files) {
        eprintln!("{}: error: Request body (from a file) and request data (key=value) cannot be mixed.", bin_name);
        std::process::exit(1);
    }

    if body_type=="json" && has_form_files {
        eprintln!("{}: error: Can't use file fields in JSON mode (perhaps you meant --form?)", bin_name);
        std::process::exit(1);
    }

    // stdin
    let mut stdin_content: Option<String> = None;
    if !ignore_stdin && !std::io::stdin().is_terminal() {
        let mut buf = String::new();
        let mut stdin = std::io::stdin();
        if stdin.read_to_string(&mut buf).is_ok() {
            stdin_content = Some(buf);
        }
    }

    if stdin_content.is_some() && (has_data_fields || has_form_files || has_body_file || raw.is_some()) {
        // Check if stdin has non-empty? Original errors even if empty? We'll error if stdin not tty and has data
        // Only if stdin content non-empty OR we are in non-tty env? For simplicity, error if stdin_content Some and has data
        // But also need to consider case where stdin is empty and no pipe? In our env, stdin is not tty and empty, we would error incorrectly for "example.com foo=bar" even without pipe.
        // To avoid that, we check if stdin_content is Some and its length >0 OR if stdin was piped? We can't differentiate.
        // Original behavior for non-tty without pipe (like in our test harness) gave POST with 0 length for GET without data, but error for GET with data? Let's see: earlier we saw "./executable --offline http://example.com 2>&1" gave POST with 0 length (because stdin not tty, empty body). And "./executable --offline http://example.com foo=bar 2>&1" gave error mixing? We saw earlier it gave error "Request body (from stdin) and request data cannot be mixed". Yes, for foo=bar with non-tty empty stdin, it errored.
        // So in non-tty environment, even empty stdin triggers mixing error when data fields present.
        // So we should error whenever ignore_stdin is false, stdin is not tty, and has_data_fields.
        // That means for our test harness, we must always pass --ignore-stdin to avoid mixing errors.
        // So for implementation, if !ignore_stdin and !stdin_is_terminal and (has_data_fields || has_form_files || has_body_file || raw.is_some()) then error.

        eprintln!("{}: error: Request body (from stdin) and request data (key=value) cannot be mixed. Pass --ignore-stdin to ignore standard input.", bin_name);
        std::process::exit(1);
    }

    let final_method = if let Some(m) = method {
        m
    } else {
        if has_data_fields || has_form_files || has_body_file || raw.is_some() || stdin_content.is_some() {
            "POST".to_string()
        } else {
            "GET".to_string()
        }
    };

    let mut final_url = parsed_url.clone();
    {
        let mut query_pairs: Vec<(String,String)> = Vec::new();
        if let Some(q) = final_url.query() {
            for (k,v) in url::form_urlencoded::parse(q.as_bytes()) {
                query_pairs.push((k.to_string(), v.to_string()));
            }
        }
        for it in &items {
            match it {
                RequestItem::UrlParam{key,value} => query_pairs.push((key.clone(), value.clone())),
                RequestItem::UrlParamFromFile{key,file_path} => {
                    let content = std::fs::read_to_string(file_path).unwrap_or_else(|_| {
                        eprintln!("{}: error: No such file or directory (os error 2)", bin_name);
                        std::process::exit(1);
                    });
                    query_pairs.push((key.clone(), content.trim_end().to_string()));
                },
                _ => {}
            }
        }
        if !query_pairs.is_empty() {
            let query_str = url::form_urlencoded::Serializer::new(String::new()).extend_pairs(query_pairs.iter().map(|(k,v)| (k.as_str(), v.as_str()))).finish();
            final_url.set_query(Some(&query_str));
        }
    }

    // format options
    let fmt_opts = parse_format_options(&format_options).unwrap_or(FormatOptions { json_indent: None, json_format: None, headers_sort: None });

    let pretty_val = if let Some(p) = pretty.clone() {
        p
    } else {
        if !std::io::stdout().is_terminal() {
            "none".to_string()
        } else {
            if std::env::var("NO_COLOR").is_ok() {
                "format".to_string()
            } else {
                if let Ok(term) = std::env::var("TERM") {
                    if term=="dumb" || term.is_empty() {
                        "format".to_string()
                    } else {
                        "all".to_string()
                    }
                } else {
                    "format".to_string()
                }
            }
        }
    };

    let headers_sort = if let Some(v) = fmt_opts.headers_sort { v } else { pretty_val=="format" || pretty_val=="all" };
    let json_format = if let Some(v) = fmt_opts.json_format { v } else { pretty_val=="format" || pretty_val=="all" };
    let json_indent = fmt_opts.json_indent.unwrap_or(4);

    let mut headers: Vec<(String,String)> = Vec::new();
    let accept_encoding = if download { "identity" } else { "gzip, deflate, br, zstd" };
    headers.push(("Accept-Encoding".to_string(), accept_encoding.to_string()));
    headers.push(("User-Agent".to_string(), format!("xh/{}", VERSION)));
    headers.push(("Connection".to_string(), "keep-alive".to_string()));

    let mut has_host_custom = false;
    let mut has_content_type_custom = false;
    let mut has_content_encoding_custom = false;
    let mut has_accept_custom = false;

    let mut custom_headers: Vec<(String,String)> = Vec::new();
    let mut headers_to_unset: Vec<String> = Vec::new();

    for it in &items {
        match it {
            RequestItem::HttpHeader{key,value} => {
                if !is_valid_header_name(key) {
                    eprintln!("{}: error: invalid HTTP header name", bin_name);
                    std::process::exit(1);
                }
                let kl = key.to_lowercase();
                if kl=="host" { has_host_custom=true; }
                if kl=="content-type" { has_content_type_custom=true; }
                if kl=="content-encoding" { has_content_encoding_custom=true; }
                if kl=="accept" { has_accept_custom=true; }
                custom_headers.push((key.clone(), value.clone()));
            },
            RequestItem::HttpHeaderFromFile{key,file_path} => {
                if !is_valid_header_name(key) {
                    eprintln!("{}: error: invalid HTTP header name", bin_name);
                    std::process::exit(1);
                }
                let content = std::fs::read_to_string(file_path).unwrap_or_else(|_| {
                    eprintln!("{}: error: No such file or directory (os error 2)", bin_name);
                    std::process::exit(1);
                });
                let kl = key.to_lowercase();
                if kl=="host" { has_host_custom=true; }
                if kl=="content-type" { has_content_type_custom=true; }
                if kl=="content-encoding" { has_content_encoding_custom=true; }
                if kl=="accept" { has_accept_custom=true; }
                custom_headers.push((key.clone(), content.trim_end().to_string()));
            },
            RequestItem::HttpHeaderToUnset{key} => {
                headers_to_unset.push(key.to_lowercase());
            },
            _ => {}
        }
    }

    headers.retain(|(k,_)| !headers_to_unset.contains(&k.to_lowercase()));
    for (k,v) in custom_headers.clone() {
        if headers_to_unset.contains(&k.to_lowercase()) { continue; }
        headers.retain(|(hk,_)| hk.to_lowercase()!=k.to_lowercase());
        headers.push((k,v));
    }

    if !has_accept_custom && !headers_to_unset.contains(&"accept".to_string()) {
        let final_accept = if body_type=="form" || body_type=="multipart" {
            "*/*"
        } else if has_body_file {
            "*/*"
        } else if has_data_fields || raw.is_some() || stdin_content.is_some() {
            "application/json, */*;q=0.5"
        } else {
            "*/*"
        };
        headers.push(("Accept".to_string(), final_accept.to_string()));
    }

    if !has_host_custom && !headers_to_unset.contains(&"host".to_string()) {
        let host = final_url.host_str().unwrap_or("").to_string();
        let port = final_url.port();
        let host_header = if let Some(p) = port { format!("{}:{}", host, p) } else { host };
        headers.push(("Host".to_string(), host_header));
    }

    let mut auth_header: Option<(String,String)> = None;
    if let Some(bearer) = bearer.clone() {
        auth_header = Some(("Authorization".to_string(), format!("Bearer {}", bearer)));
    } else if let Some(auth) = auth.clone() {
        let auth_type_val = auth_type.clone().unwrap_or_else(|| "basic".to_string());
        match auth_type_val.as_str() {
            "bearer" => {
                auth_header = Some(("Authorization".to_string(), format!("Bearer {}", auth)));
            },
            "basic" => {
                let encoded = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, auth.as_bytes());
                auth_header = Some(("Authorization".to_string(), format!("Basic {}", encoded)));
            },
            _ => {}
        }
    }
    if let Some((k,v)) = auth_header {
        if !headers_to_unset.contains(&k.to_lowercase()) {
            headers.push((k,v));
        }
    }

    let mut body_string: Option<String> = None;
    let mut content_type: Option<String> = None;
    let mut is_multipart = false;

    if let Some(raw_val) = raw.clone() {
        body_string = Some(raw_val.clone());
        content_type = Some("application/json".to_string());
    } else if has_body_file {
        for it in &items {
            match it {
                RequestItem::BodyFile{file_name,file_type} => {
                    let ft = file_type.clone().or_else(|| guess_mime(file_name));
                    content_type = ft;
                    let content = std::fs::read(file_name).unwrap_or_else(|_| {
                        eprintln!("{}: error: No such file or directory (os error 2)", bin_name);
                        std::process::exit(1);
                    });
                    body_string = Some(String::from_utf8_lossy(&content).to_string());
                    break;
                },
                RequestItem::FormFile{key,file_name,file_type,_file_name_header} => {
                    if key.is_empty() {
                        let ft = file_type.clone().or_else(|| guess_mime(file_name));
                        content_type = ft;
                        let content = std::fs::read(file_name).unwrap_or_else(|_| {
                            eprintln!("{}: error: No such file or directory (os error 2)", bin_name);
                            std::process::exit(1);
                        });
                        body_string = Some(String::from_utf8_lossy(&content).to_string());
                        break;
                    }
                },
                _ => {}
            }
        }
    } else if let Some(ref stdin_buf) = stdin_content {
        if !stdin_buf.is_empty() {
            body_string = Some(stdin_buf.clone());
        } else {
            body_string = Some("".to_string());
        }
        content_type = Some("application/json".to_string());
    } else if body_type=="json" && has_data_fields {
        let mut json_fields: Vec<(String, serde_json::Value)> = Vec::new();
        for it in &items {
            match it {
                RequestItem::DataField{raw_key,value,..} => {
                    json_fields.push((raw_key.clone(), serde_json::Value::String(value.clone())));
                },
                RequestItem::DataFieldFromFile{raw_key,file_path,..} => {
                    let content = std::fs::read_to_string(file_path).unwrap_or_else(|_| {
                        eprintln!("{}: error: No such file or directory (os error 2)", bin_name);
                        std::process::exit(1);
                    });
                    json_fields.push((raw_key.clone(), serde_json::Value::String(content)));
                },
                RequestItem::JsonField{raw_key,json_value,..} => {
                    json_fields.push((raw_key.clone(), json_value.clone()));
                },
                _ => {}
            }
        }
        let json_val = build_json_from_data(json_fields);
        let json_str = if json_format {
            if json_indent==2 {
                serde_json::to_string_pretty(&json_val).unwrap().replace("    ", "  ")
            } else {
                serde_json::to_string_pretty(&json_val).unwrap()
            }
        } else {
            serde_json::to_string(&json_val).unwrap()
        };
        body_string = Some(json_str);
        content_type = Some("application/json".to_string());
    } else if body_type=="form" {
        if has_form_files {
            is_multipart=true;
            let boundary = generate_boundary();
            content_type=Some(format!("multipart/form-data; boundary={}", boundary));
            let mut mp_body=String::new();
            for it in &items {
                match it {
                    RequestItem::DataField{key,value,..} => {
                        mp_body.push_str(&format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"\r\n\r\n{}\r\n", boundary, key, value));
                    },
                    RequestItem::DataFieldFromFile{key,file_path,..} => {
                        let content = std::fs::read_to_string(file_path).unwrap_or_else(|_| {
                            eprintln!("{}: error: No such file or directory (os error 2)", bin_name);
                            std::process::exit(1);
                        });
                        mp_body.push_str(&format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"\r\n\r\n{}\r\n", boundary, key, content));
                    },
                    RequestItem::FormFile{key,file_name,file_type,file_name_header} => {
                        if key.is_empty() { continue; }
                        let filename = file_name_header.clone().unwrap_or_else(|| Path::new(file_name).file_name().and_then(|s| s.to_str()).unwrap_or("file").to_string());
                        let file_content = std::fs::read(file_name).unwrap_or_else(|_| {
                            eprintln!("{}: error: No such file or directory (os error 2)", bin_name);
                            std::process::exit(1);
                        });
                        let file_str = String::from_utf8_lossy(&file_content);
                        if let Some(ct_val)=file_type {
                            mp_body.push_str(&format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\nContent-Type: {}\r\n\r\n{}\r\n", boundary, key, filename, ct_val, file_str));
                        } else {
                            mp_body.push_str(&format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\n\r\n{}\r\n", boundary, key, filename, file_str));
                        }
                    },
                    _ => {}
                }
            }
            mp_body.push_str(&format!("--{}--\r\n", boundary));
            body_string=Some(mp_body);
        } else {
            let mut pairs: Vec<(String,String)> = Vec::new();
            for it in &items {
                match it {
                    RequestItem::DataField{key,value,..} => pairs.push((key.clone(), value.clone())),
                    RequestItem::DataFieldFromFile{key,file_path,..} => {
                        let content = std::fs::read_to_string(file_path).unwrap_or_else(|_| {
                            eprintln!("{}: error: No such file or directory (os error 2)", bin_name);
                            std::process::exit(1);
                        });
                        pairs.push((key.clone(), content.trim_end().to_string()));
                    },
                    RequestItem::JsonField{key,json_value,..} => pairs.push((key.clone(), json_value.to_string())),
                    _ => {}
                }
            }
            let encoded = url::form_urlencoded::Serializer::new(String::new()).extend_pairs(pairs).finish();
            body_string=Some(encoded);
            content_type=Some("application/x-www-form-urlencoded".to_string());
        }
    } else if body_type=="multipart" {
        is_multipart=true;
        let boundary = generate_boundary();
        content_type=Some(format!("multipart/form-data; boundary={}", boundary));
        let mut mp_body=String::new();
        for it in &items {
            match it {
                RequestItem::DataField{key,value,..} => {
                    mp_body.push_str(&format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"\r\n\r\n{}\r\n", boundary, key, value));
                },
                RequestItem::DataFieldFromFile{key,file_path,..} => {
                    let content = std::fs::read_to_string(file_path).unwrap_or_else(|_| {
                        eprintln!("{}: error: No such file or directory (os error 2)", bin_name);
                        std::process::exit(1);
                    });
                    mp_body.push_str(&format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"\r\n\r\n{}\r\n", boundary, key, content));
                },
                RequestItem::FormFile{key,file_name,file_type,file_name_header} => {
                    if key.is_empty() { continue; }
                    let filename = file_name_header.clone().unwrap_or_else(|| Path::new(file_name).file_name().and_then(|s| s.to_str()).unwrap_or("file").to_string());
                    let file_content = std::fs::read(file_name).unwrap_or_else(|_| {
                        eprintln!("{}: error: No such file or directory (os error 2)", bin_name);
                        std::process::exit(1);
                    });
                    let file_str = String::from_utf8_lossy(&file_content);
                    if let Some(ct_val)=file_type {
                        mp_body.push_str(&format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\nContent-Type: {}\r\n\r\n{}\r\n", boundary, key, filename, ct_val, file_str));
                    } else {
                        mp_body.push_str(&format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\n\r\n{}\r\n", boundary, key, filename, file_str));
                    }
                },
                _ => {}
            }
        }
        mp_body.push_str(&format!("--{}--\r\n", boundary));
        body_string=Some(mp_body);
    }

    if let Some(ct)=content_type.clone() {
        if !has_content_type_custom && !headers_to_unset.contains(&"content-type".to_string()) {
            headers.push(("Content-Type".to_string(), ct));
        }
    }

    if let Some(body) = body_string.clone() {
        if !headers_to_unset.contains(&"content-length".to_string()) && !is_multipart {
            headers.push(("Content-Length".to_string(), body.len().to_string()));
        }
    }

    if compress>0 && has_content_encoding_custom {
        eprintln!("{}: warning: --compress can't be used with a 'Content-Encoding:' header. --compress will be disabled.", bin_name);
    }

    if headers_sort {
        headers.sort_by(|a,b| a.0.to_lowercase().cmp(&b.0.to_lowercase()));
    }

    let mut print_opt_val = print.clone();
    if headers {
        print_opt_val=Some("h".to_string());
    }
    if body_flag {
        print_opt_val=Some("b".to_string());
    }
    if meta {
        print_opt_val=Some("m".to_string());
    }
    if verbose>=1 && print_opt_val.is_none() {
        print_opt_val=Some("HB".to_string());
    }

    let print_str = print_opt_val.unwrap_or_else(|| if body_string.is_some() { "HB".to_string() } else { "H".to_string() });

    if curl {
        if offline {
            eprintln!("Warning: Ignored --offline");
        }
        let mut warnings=Vec::new();
        if print.is_some() || headers || body_flag || meta {
            warnings.push("-p/--print");
        }
        if body_flag {
            warnings.push("-b/--body");
        }
        if pretty.is_some() {
            warnings.push("--pretty");
        }
        if style.is_some() {
            warnings.push("-s/--style");
        }
        if response_charset.is_some() {
            warnings.push("--response-charset");
        }
        if response_mime.is_some() {
            warnings.push("--response-mime");
        }
        if session.is_some() {
            warnings.push("--session");
        }
        if session_read_only.is_some() {
            warnings.push("--session-read-only");
        }
        if history_print.is_some() {
            warnings.push("-P/--history-print");
        }
        if all {
            warnings.push("--all");
        }
        if verbose>0 && !warnings.contains(&"--all") {
            warnings.push("--all");
        }
        for w in warnings {
            eprintln!("Warning: Ignored {}", w);
        }

        let explicit_method = method.is_some();
        let method_str = final_method.clone();
        let mut curl_parts: Vec<String> = Vec::new();
        curl_parts.push("curl".to_string());

        if follow {
            curl_parts.push("-L".to_string());
        }
        if download && output.is_none() {
            curl_parts.push("-f".to_string());
            curl_parts.push("-L".to_string());
            curl_parts.push("-O".to_string());
        }

        let needs_x = if explicit_method { true } else { final_method!="GET" };
        if needs_x {
            if curl_long {
                curl_parts.push("--request".to_string());
            } else {
                curl_parts.push("-X".to_string());
            }
            curl_parts.push(method_str.clone());
        }

        let url_for_curl = final_url.to_string();
        let url_quoted = if url_for_curl.contains('?') || url_for_curl.contains('&') || url_for_curl.contains(' ') || url_for_curl.contains('\'') {
            let escaped = url_for_curl.replace('\'', "'\\''");
            format!("'{}'", escaped)
        } else {
            url_for_curl.clone()
        };
        curl_parts.push(url_quoted);

        if let Some(auth_val) = auth.clone() {
            let auth_type_val = auth_type.clone().unwrap_or_else(|| "basic".to_string());
            match auth_type_val.as_str() {
                "basic" => {
                    if curl_long {
                        curl_parts.push("--basic".to_string());
                        curl_parts.push("--user".to_string());
                    } else {
                        curl_parts.push("--basic".to_string());
                        curl_parts.push("-u".to_string());
                    }
                    curl_parts.push(auth_val.clone());
                },
                "digest" => {
                    if curl_long {
                        curl_parts.push("--digest".to_string());
                        curl_parts.push("--user".to_string());
                    } else {
                        curl_parts.push("--digest".to_string());
                        curl_parts.push("-u".to_string());
                    }
                    curl_parts.push(auth_val.clone());
                },
                "bearer" => {
                    curl_parts.push("--oauth2-bearer".to_string());
                    curl_parts.push(auth_val.clone());
                },
                _ => {}
            }
        } else if let Some(bearer_val) = bearer.clone() {
            curl_parts.push("--oauth2-bearer".to_string());
            curl_parts.push(bearer_val.clone());
        }

        if let Some(v) = verify.clone() {
            if v=="no" || v=="false" {
                if curl_long {
                    curl_parts.push("--insecure".to_string());
                } else {
                    curl_parts.push("-k".to_string());
                }
            }
        }

        let mut final_curl_headers: Vec<(String,String)> = Vec::new();
        if let Some((_,v)) = headers.iter().find(|(k,_)| k.to_lowercase()=="content-type") {
            if !is_multipart {
                final_curl_headers.push(("content-type".to_string(), v.clone()));
            }
        }
        if let Some((_,v)) = headers.iter().find(|(k,_)| k.to_lowercase()=="accept") {
            if v!="*/*" {
                final_curl_headers.push(("accept".to_string(), v.clone()));
            }
        }
        for (k,v) in custom_headers.clone() {
            let kl = k.to_lowercase();
            if kl=="host" || kl=="content-length" || kl=="connection" || kl=="accept-encoding" || kl=="user-agent" || kl=="content-type" || kl=="accept" {
                continue;
            }
            final_curl_headers.push((k.clone(), v.clone()));
        }

        for (k,v) in final_curl_headers {
            let header_str = if v.is_empty() { format!("{}:", k) } else { format!("{}: {}", k, v) };
            let quoted = shell_quote(&header_str);
            if curl_long {
                curl_parts.push("--header".to_string());
            } else {
                curl_parts.push("-H".to_string());
            }
            curl_parts.push(quoted);
        }

        if let Some(body) = body_string.clone() {
            if is_multipart {
                curl_parts.retain(|p| !p.contains("multipart") && !p.contains("content-type"));
                for it in &items {
                    match it {
                        RequestItem::DataField{key,value,..} => {
                            let field = format!("{}={}", key, value);
                            let quoted = shell_quote(&field);
                            if curl_long {
                                curl_parts.push("--form".to_string());
                            } else {
                                curl_parts.push("-F".to_string());
                            }
                            curl_parts.push(quoted);
                        },
                        RequestItem::FormFile{key,file_name,file_type,file_name_header} => {
                            let mut spec = format!("{}=@{}", key, file_name);
                            if let Some(t) = file_type {
                                spec.push_str(&format!(";type={}", t));
                            }
                            if let Some(fn_) = file_name_header {
                                spec.push_str(&format!(";filename={}", fn_));
                            }
                            let quoted = shell_quote(&spec);
                            if curl_long {
                                curl_parts.push("--form".to_string());
                            } else {
                                curl_parts.push("-F".to_string());
                            }
                            curl_parts.push(quoted);
                        },
                        _ => {}
                    }
                }
            } else if body_type=="form" && !is_multipart {
                for it in &items {
                    match it {
                        RequestItem::DataField{key,value,..} => {
                            let field = format!("{}={}", key, value);
                            let quoted = shell_quote(&field);
                            curl_parts.push("--data-urlencode".to_string());
                            curl_parts.push(quoted);
                        },
                        RequestItem::DataFieldFromFile{key,file_path,..} => {
                            let content = std::fs::read_to_string(file_path).unwrap_or_default();
                            let field = format!("{}={}", key, content.trim_end());
                            let quoted = shell_quote(&field);
                            curl_parts.push("--data-urlencode".to_string());
                            curl_parts.push(quoted);
                        },
                        _ => {}
                    }
                }
            } else if has_body_file {
                for it in &items {
                    match it {
                        RequestItem::BodyFile{file_name,..} => {
                            let arg = format!("@{}", file_name);
                            curl_parts.push("--data-binary".to_string());
                            curl_parts.push(arg);
                        },
                        RequestItem::FormFile{key,file_name,..} => {
                            if key.is_empty() {
                                let arg = format!("@{}", file_name);
                                curl_parts.push("--data-binary".to_string());
                                curl_parts.push(arg);
                            }
                        },
                        _ => {}
                    }
                }
            } else {
                let quoted_body = shell_quote(&body);
                if curl_long {
                    curl_parts.push("--data".to_string());
                } else {
                    curl_parts.push("-d".to_string());
                }
                curl_parts.push(quoted_body);
            }
        }

        if output.is_some() {
            let out_path = output.unwrap();
            if curl_long {
                curl_parts.push("--output".to_string());
            } else {
                curl_parts.push("-o".to_string());
            }
            curl_parts.push(out_path.to_string_lossy().to_string());
        }

        println!("{}", curl_parts.join(" "));
        std::process::exit(0);
    }

    if offline {
        let mut out = String::new();
        let path = final_url.path();
        let query = final_url.query().map(|q| format!("?{}", q)).unwrap_or_default();
        let request_line = format!("{} {}{} HTTP/1.1", final_method, path, query);

        if print_str.contains('H') {
            let is_color = pretty_val=="all" || pretty_val=="colors";
            if is_color {
                let colored_line = format!("\x1b[0m\x1b[32m{}\x1b[0m \x1b[0m\x1b[4m\x1b[36m{}\x1b[0m \x1b[0m\x1b[34mHTTP\x1b[0m/\x1b[0m\x1b[34m1.1\x1b[0m", final_method, format!("{}{}", path, query));
                out.push_str(&colored_line);
                out.push_str("\n");
                for (k,v) in &headers {
                    out.push_str(&format!("\x1b[0m\x1b[36m{}\x1b[0m:\x1b[0m \x1b[0m{}\x1b[0m\n", k, v));
                }
            } else {
                out.push_str(&format!("{}\n", request_line));
                for (k,v) in &headers {
                    out.push_str(&format!("{}: {}\n", k, v));
                }
            }
            out.push_str("\n");
        }

        if print_str.contains('B') {
            if let Some(body) = body_string {
                out.push_str(&body);
                out.push_str("\n");
                out.push_str("\n");
            }
        }

        print!("{}", out);
        std::process::exit(0);
    }

    eprintln!("{}: error: Network requests not implemented in this clone, use --offline", bin_name);
    std::process::exit(1);
}

fn build_command(bin_name: &str) -> Command {
    Command::new(bin_name)
        .version(VERSION)
        .about("xh is a friendly and fast tool for sending HTTP requests")
        .arg(Arg::new("<[METHOD] URL>").required(false).help("The request URL, preceded by an optional HTTP method"))
        .arg(Arg::new("[REQUEST_ITEM]...").num_args(0..).help("Optional key-value pairs to be included in the request"))
        .arg(Arg::new("json").short('j').long("json").action(ArgAction::SetTrue).help("(default) Serialize data items from the command line as a JSON object"))
        .arg(Arg::new("form").short('f').long("form").action(ArgAction::SetTrue).help("Serialize data items from the command line as form fields"))
        .arg(Arg::new("multipart").long("multipart").action(ArgAction::SetTrue).help("Like --form, but force a multipart/form-data request even without files"))
        .arg(Arg::new("raw").long("raw").value_name("RAW").help("Pass raw request data without extra processing"))
        .arg(Arg::new("pretty").long("pretty").value_name("STYLE").value_parser(value_parser!(String)).help("Controls output processing"))
        .arg(Arg::new("format-options").long("format-options").value_name("FORMAT_OPTIONS").action(ArgAction::Append).help("Set output formatting options"))
        .arg(Arg::new("style").short('s').long("style").value_name("THEME").value_parser(value_parser!(String)).help("Output coloring style"))
        .arg(Arg::new("response-charset").long("response-charset").value_name("ENCODING").help("Override the response encoding for terminal display purposes"))
        .arg(Arg::new("response-mime").long("response-mime").value_name("MIME_TYPE").help("Override the response mime type for coloring and formatting for the terminal"))
        .arg(Arg::new("print").short('p').long("print").value_name("FORMAT").help("String specifying what the output should contain"))
        .arg(Arg::new("headers").short('h').long("headers").action(ArgAction::SetTrue).help("Print only the response headers. Shortcut for --print=h"))
        .arg(Arg::new("body").short('b').long("body").action(ArgAction::SetTrue).help("Print only the response body. Shortcut for --print=b"))
        .arg(Arg::new("meta").short('m').long("meta").action(ArgAction::SetTrue).help("Print only the response metadata. Shortcut for --print=m"))
        .arg(Arg::new("verbose").short('v').long("verbose").action(ArgAction::Count).help("Print the whole request as well as the response"))
        .arg(Arg::new("debug").long("debug").action(ArgAction::SetTrue).help("Print full error stack traces and debug log messages"))
        .arg(Arg::new("all").long("all").action(ArgAction::SetTrue).help("Show any intermediary requests/responses while following redirects with --follow"))
        .arg(Arg::new("history-print").short('P').long("history-print").value_name("FORMAT").help("The same as --print but applies only to intermediary requests/responses"))
        .arg(Arg::new("quiet").short('q').long("quiet").action(ArgAction::Count).help("Do not print to stdout or stderr"))
        .arg(Arg::new("stream").short('S').long("stream").action(ArgAction::SetTrue).help("Always stream the response body"))
        .arg(Arg::new("compress").short('x').long("compress").action(ArgAction::Count).help("Content compressed (encoded) with Deflate algorithm"))
        .arg(Arg::new("output").short('o').long("output").value_name("FILE").value_parser(value_parser!(PathBuf)).help("Save output to FILE instead of stdout"))
        .arg(Arg::new("download").short('d').long("download").action(ArgAction::SetTrue).help("Download the body to a file instead of printing it"))
        .arg(Arg::new("continue").short('c').long("continue").action(ArgAction::SetTrue).help("Resume an interrupted download. Requires --download and --output"))
        .arg(Arg::new("session").long("session").value_name("FILE").value_parser(value_parser!(PathBuf)).help("Create, or reuse and update a session"))
        .arg(Arg::new("session-read-only").long("session-read-only").value_name("FILE").value_parser(value_parser!(PathBuf)).help("Create or read a session without updating it from the request/response exchange"))
        .arg(Arg::new("auth-type").short('A').long("auth-type").value_name("AUTH_TYPE").help("Specify the auth mechanism"))
        .arg(Arg::new("auth").short('a').long("auth").value_name("USER[:PASS] | TOKEN").help("Authenticate as USER with PASS (-A basic|digest) or with TOKEN (-A bearer)"))
        .arg(Arg::new("bearer").long("bearer").value_name("TOKEN").help("Authenticate with a bearer token"))
        .arg(Arg::new("ignore-netrc").long("ignore-netrc").action(ArgAction::SetTrue).help("Do not use credentials from .netrc"))
        .arg(Arg::new("offline").long("offline").action(ArgAction::SetTrue).help("Construct HTTP requests without sending them anywhere"))
        .arg(Arg::new("check-status").long("check-status").action(ArgAction::SetTrue).help("(default) Exit with an error status code if the server replies with an error"))
        .arg(Arg::new("follow").short('F').long("follow").action(ArgAction::SetTrue).help("Do follow redirects"))
        .arg(Arg::new("max-redirects").long("max-redirects").value_name("NUM").value_parser(value_parser!(u32)).help("Number of redirects to follow. Only respected if --follow is used"))
        .arg(Arg::new("timeout").long("timeout").value_name("SEC").value_parser(parse_timeout).help("Connection timeout of the request"))
        .arg(Arg::new("proxy").long("proxy").value_name("PROTOCOL:URL").action(ArgAction::Append).help("Use a proxy for a protocol. For example: --proxy https:http://proxy.host:8080"))
        .arg(Arg::new("verify").long("verify").value_name("VERIFY").help("If \"no\", skip SSL verification. If a file path, use it as a CA bundle"))
        .arg(Arg::new("cert").long("cert").value_name("FILE").value_parser(value_parser!(PathBuf)).help("Use a client side certificate for SSL"))
        .arg(Arg::new("cert-key").long("cert-key").value_name("FILE").value_parser(value_parser!(PathBuf)).help("A private key file to use with --cert"))
        .arg(Arg::new("ssl").long("ssl").value_name("VERSION").help("Force a particular TLS version"))
        .arg(Arg::new("native-tls").long("native-tls").action(ArgAction::SetTrue).help("Use the system TLS library instead of rustls (if enabled at compile time)"))
        .arg(Arg::new("default-scheme").long("default-scheme").value_name("SCHEME").help("The default scheme to use if not specified in the URL"))
        .arg(Arg::new("https").long("https").action(ArgAction::SetTrue).help("Make HTTPS requests if not specified in the URL"))
        .arg(Arg::new("http-version").long("http-version").value_name("VERSION").help("HTTP version to use"))
        .arg(Arg::new("resolve").long("resolve").value_name("HOST:ADDRESS").action(ArgAction::Append).help("Override DNS resolution for specific domain to a custom IP"))
        .arg(Arg::new("interface").long("interface").value_name("NAME").help("Bind to a network interface or local IP address"))
        .arg(Arg::new("ipv4").short('4').long("ipv4").action(ArgAction::SetTrue).help("Resolve hostname to ipv4 addresses only"))
        .arg(Arg::new("ipv6").short('6').long("ipv6").action(ArgAction::SetTrue).help("Resolve hostname to ipv6 addresses only"))
        .arg(Arg::new("unix-socket").long("unix-socket").value_name("FILE").value_parser(value_parser!(PathBuf)).help("Connect using a Unix domain socket"))
        .arg(Arg::new("ignore-stdin").short('I').long("ignore-stdin").action(ArgAction::SetTrue).help("Do not attempt to read stdin"))
        .arg(Arg::new("curl").long("curl").action(ArgAction::SetTrue).help("Print a translation to a curl command"))
        .arg(Arg::new("curl-long").long("curl-long").action(ArgAction::SetTrue).help("Use the long versions of curl's flags"))
        .arg(Arg::new("generate").long("generate").value_name("KIND").help("Generate shell completions or man pages"))
}

fn parse_timeout(s: &str) -> Result<f64, String> {
    s.parse::<f64>().map_err(|_| format!("Connection timeout is not a valid number"))
}

#[derive(Debug, Clone, PartialEq)]
enum RequestItem {
    DataField { key: String, raw_key: String, value: String },
    DataFieldFromFile { key: String, raw_key: String, file_path: String },
    JsonField { key: String, raw_key: String, json_value: serde_json::Value },
    UrlParam { key: String, value: String },
    UrlParamFromFile { key: String, file_path: String },
    HttpHeader { key: String, value: String },
    HttpHeaderFromFile { key: String, file_path: String },
    HttpHeaderToUnset { key: String },
    FormFile { key: String, file_name: String, file_type: Option<String>, file_name_header: Option<String> },
    BodyFile { file_name: String, file_type: Option<String> },
}

fn unescape_key(s: &str) -> String {
    let mut res = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c=='\\' {
            if let Some(next)=chars.next() { res.push(next); }
        } else { res.push(c); }
    }
    res
}

fn find_unescaped_bytes(s: &str, pat: &str) -> Option<usize> {
    let bytes = s.as_bytes();
    let pat_bytes = pat.as_bytes();
    let mut i=0;
    while i+pat_bytes.len()<=bytes.len() {
        if bytes[i]==b'\\' { i+=2; continue; }
        if &bytes[i..i+pat_bytes.len()]==pat_bytes {
            return Some(i);
        }
        i+=1;
    }
    None
}

fn parse_file_spec(spec: &str) -> (String, Option<String>, Option<String>) {
    let mut parts = spec.split(';');
    let file_name = parts.next().unwrap_or("").to_string();
    let mut file_type=None;
    let mut file_name_header=None;
    for part in parts {
        if part.starts_with("type=") { file_type=Some(part[5..].to_string()); }
        else if part.starts_with("filename=") { file_name_header=Some(part[9..].to_string()); }
    }
    (file_name, file_type, file_name_header)
}

fn parse_request_item(item: &str) -> Result<RequestItem, String> {
    if item.starts_with('@') {
        let rest=&item[1..];
        let (file_name,file_type,_)=parse_file_spec(rest);
        return Ok(RequestItem::BodyFile { file_name, file_type });
    }
    if let Some(pos)=find_unescaped_bytes(item, "==") {
        let key_part=&item[..pos];
        let value_part=&item[pos+2..];
        let key=unescape_key(key_part);
        if value_part.starts_with('@') {
            return Ok(RequestItem::UrlParamFromFile { key, file_path: value_part[1..].to_string() });
        } else {
            return Ok(RequestItem::UrlParam { key, value: unescape_key(value_part) });
        }
    }
    if let Some(pos)=find_unescaped_bytes(item, ":=") {
        let key_part=&item[..pos];
        let value_part=&item[pos+2..];
        let raw_key=key_part.to_string();
        let key=unescape_key(key_part);
        if value_part.starts_with('@') {
            let file_path=&value_part[1..];
            let content=std::fs::read_to_string(file_path).map_err(|e| format!("No such file or directory (os error {})", e.raw_os_error().unwrap_or(2)))?;
            let json_val: serde_json::Value=serde_json::from_str(&content).map_err(|e| format!("{:?}", e))?;
            return Ok(RequestItem::JsonField { key, raw_key, json_value: json_val });
        } else {
            let json_val: serde_json::Value=serde_json::from_str(value_part).map_err(|_| format!("Invalid value for '[REQUEST_ITEM]...': {:?} expected value at line 1 column 1", item))?;
            return Ok(RequestItem::JsonField { key, raw_key, json_value: json_val });
        }
    }
    if let Some(eq_pos)=find_unescaped_bytes(item, "=") {
        let key_part=&item[..eq_pos];
        let value_part=&item[eq_pos+1..];
        if value_part.starts_with('@') {
            let raw_key=key_part.to_string();
            let key=unescape_key(key_part);
            return Ok(RequestItem::DataFieldFromFile { key, raw_key, file_path: value_part[1..].to_string() });
        } else {
            let raw_key=key_part.to_string();
            let key=unescape_key(key_part);
            let value=unescape_key(value_part);
            return Ok(RequestItem::DataField { key, raw_key, value });
        }
    }
    if let Some(at_pos)=find_unescaped_bytes(item, "@") {
        if at_pos>0 {
            let key_part=&item[..at_pos];
            let file_spec=&item[at_pos+1..];
            let (file_name,file_type,file_name_header)=parse_file_spec(file_spec);
            let key=unescape_key(key_part);
            return Ok(RequestItem::FormFile { key, file_name, file_type, file_name_header });
        }
    }
    if let Some(colon_pos)=find_unescaped_bytes(item, ":") {
        let key_part=&item[..colon_pos];
        let value_part=&item[colon_pos+1..];
        let key=unescape_key(key_part);
        if value_part.is_empty() {
            return Ok(RequestItem::HttpHeaderToUnset { key });
        } else if value_part.starts_with('@') {
            return Ok(RequestItem::HttpHeaderFromFile { key, file_path: value_part[1..].to_string() });
        } else {
            return Ok(RequestItem::HttpHeader { key, value: unescape_key(value_part) });
        }
    }
    if item.ends_with(';') {
        let key_part=&item[..item.len()-1];
        if !key_part.is_empty() {
            return Ok(RequestItem::HttpHeader { key: unescape_key(key_part), value: "".to_string() });
        }
    }
    Err(format!("Invalid value for '[REQUEST_ITEM]...': {:?}", item))
}

#[derive(Debug)]
struct FormatOptions {
    json_indent: Option<usize>,
    json_format: Option<bool>,
    headers_sort: Option<bool>,
}

fn parse_format_options(opts: &[String]) -> Result<FormatOptions, String> {
    let mut json_indent=None;
    let mut json_format=None;
    let mut headers_sort=None;
    for opt_str in opts {
        for part in opt_str.split(',') {
            if part.trim().is_empty() { continue; }
            let kv: Vec<&str>=part.splitn(2,':').collect();
            if kv.len()!=2 { return Err(format!("Invalid format option {}", part)); }
            let k=kv[0].trim();
            let v=kv[1].trim();
            match k {
                "json.indent" => { json_indent=Some(v.parse().map_err(|_| format!("Invalid indent"))?); },
                "json.format" => {
                    match v {
                        "true" => json_format=Some(true),
                        "false" => json_format=Some(false),
                        _ => return Err(format!("Invalid json.format")),
                    }
                },
                "headers.sort" => {
                    match v {
                        "true" => headers_sort=Some(true),
                        "false" => headers_sort=Some(false),
                        _ => return Err(format!("Invalid headers.sort")),
                    }
                },
                _ => return Err(format!("Unknown format option {}", k)),
            }
        }
    }
    Ok(FormatOptions { json_indent, json_format, headers_sort })
}

