fn parse_url_custom(input: &str, default_scheme: &str) -> Result<url::Url, String> {
    let mut url_str = input.to_string();
    if url_str.starts_with("://") {
        let scheme = if default_scheme.is_empty() { "http" } else { default_scheme };
        url_str = format!("{}://{}", scheme, &url_str[3..]);
    } else if url_str.starts_with(':') {
        let scheme = if default_scheme.is_empty() { "http" } else { default_scheme };
        if url_str.len()>=2 && url_str.chars().nth(1)==Some('/') {
            url_str = format!("{}://localhost{}", scheme, &url_str[1..]);
        } else {
            if let Some(slash_idx) = url_str.find('/') {
                let port_part = &url_str[..slash_idx];
                let path_part = &url_str[slash_idx..];
                url_str = format!("{}://localhost{}{}", scheme, port_part, path_part);
            } else {
                url_str = format!("{}://localhost{}", scheme, url_str);
            }
        }
    } else if !url_str.contains("://") {
        let scheme = if default_scheme.is_empty() { "http" } else { default_scheme };
        url_str = format!("{}://{}", scheme, url_str);
    }
    url::Url::parse(&url_str).map_err(|e| {
        let err_str = e.to_string();
        if err_str.contains("invalid port") {
            "Invalid <URL>: invalid port number".to_string()
        } else {
            format!("Invalid <URL>: {}", err_str)
        }
    })
}

