fn parse_timeout(s: &str) -> Result<f64, String> {
    s.parse::<f64>().map_err(|_| format!("Connection timeout is not a valid number"))
}

#[derive(Debug, Clone, PartialEq)]
enum RequestItem {
    DataField { key: String, raw_key: String, value: String },
    DataFieldFromFile { key: String, raw_key: String, file_path: String },
    JsonField { key: String, raw_key: String, json_value: serde_json::Value },
    UrlParam { key: String, value: String },
    UrlParamFromFile { key: String, file_path: String },
    HttpHeader { key: String, value: String },
    HttpHeaderFromFile { key: String, file_path: String },
    HttpHeaderToUnset { key: String },
    FormFile { key: String, file_name: String, file_type: Option<String>, file_name_header: Option<String> },
    BodyFile { file_name: String, file_type: Option<String> },
}

fn unescape_key(s: &str) -> String {
    let mut res = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c=='\\' {
            if let Some(next)=chars.next() { res.push(next); }
        } else { res.push(c); }
    }
    res
}

fn find_unescaped_bytes(s: &str, pat: &str) -> Option<usize> {
    let bytes = s.as_bytes();
    let pat_bytes = pat.as_bytes();
    let mut i=0;
    while i+pat_bytes.len()<=bytes.len() {
        if bytes[i]==b'\\' { i+=2; continue; }
        if &bytes[i..i+pat_bytes.len()]==pat_bytes {
            return Some(i);
        }
        i+=1;
    }
    None
}

fn parse_file_spec(spec: &str) -> (String, Option<String>, Option<String>) {
    let mut parts = spec.split(';');
    let file_name = parts.next().unwrap_or("").to_string();
    let mut file_type=None;
    let mut file_name_header=None;
    for part in parts {
        if part.starts_with("type=") { file_type=Some(part[5..].to_string()); }
        else if part.starts_with("filename=") { file_name_header=Some(part[9..].to_string()); }
    }
    (file_name, file_type, file_name_header)
}

fn parse_request_item(item: &str) -> Result<RequestItem, String> {
    if item.starts_with('@') {
        let rest=&item[1..];
        let (file_name,file_type,_)=parse_file_spec(rest);
        return Ok(RequestItem::BodyFile { file_name, file_type });
    }
    if let Some(pos)=find_unescaped_bytes(item, "==") {
        let key_part=&item[..pos];
        let value_part=&item[pos+2..];
        let key=unescape_key(key_part);
        if value_part.starts_with('@') {
            return Ok(RequestItem::UrlParamFromFile { key, file_path: value_part[1..].to_string() });
        } else {
            return Ok(RequestItem::UrlParam { key, value: unescape_key(value_part) });
        }
    }
    if let Some(pos)=find_unescaped_bytes(item, ":=") {
        let key_part=&item[..pos];
        let value_part=&item[pos+2..];
        let raw_key=key_part.to_string();
        let key=unescape_key(key_part);
        if value_part.starts_with('@') {
            let file_path=&value_part[1..];
            let content=std::fs::read_to_string(file_path).map_err(|e| format!("No such file or directory (os error {})", e.raw_os_error().unwrap_or(2)))?;
            let json_val: serde_json::Value=serde_json::from_str(&content).map_err(|e| format!("{:?}", e))?;
            return Ok(RequestItem::JsonField { key, raw_key, json_value: json_val });
        } else {
            let json_val: serde_json::Value=serde_json::from_str(value_part).map_err(|_| format!("Invalid value for '[REQUEST_ITEM]...': {:?} expected value at line 1 column 1", item))?;
            return Ok(RequestItem::JsonField { key, raw_key, json_value: json_val });
        }
    }
    if let Some(eq_pos)=find_unescaped_bytes(item, "=") {
        let key_part=&item[..eq_pos];
        let value_part=&item[eq_pos+1..];
        if value_part.starts_with('@') {
            let raw_key=key_part.to_string();
            let key=unescape_key(key_part);
            return Ok(RequestItem::DataFieldFromFile { key, raw_key, file_path: value_part[1..].to_string() });
        } else {
            let raw_key=key_part.to_string();
            let key=unescape_key(key_part);
            let value=unescape_key(value_part);
            return Ok(RequestItem::DataField { key, raw_key, value });
        }
    }
    if let Some(at_pos)=find_unescaped_bytes(item, "@") {
        if at_pos>0 {
            let key_part=&item[..at_pos];
            let file_spec=&item[at_pos+1..];
            let (file_name,file_type,file_name_header)=parse_file_spec(file_spec);
            let key=unescape_key(key_part);
            return Ok(RequestItem::FormFile { key, file_name, file_type, file_name_header });
        }
    }
    if let Some(colon_pos)=find_unescaped_bytes(item, ":") {
        let key_part=&item[..colon_pos];
        let value_part=&item[colon_pos+1..];
        let key=unescape_key(key_part);
        if value_part.is_empty() {
            return Ok(RequestItem::HttpHeaderToUnset { key });
        } else if value_part.starts_with('@') {
            return Ok(RequestItem::HttpHeaderFromFile { key, file_path: value_part[1..].to_string() });
        } else {
            return Ok(RequestItem::HttpHeader { key, value: unescape_key(value_part) });
        }
    }
    if item.ends_with(';') {
        let key_part=&item[..item.len()-1];
        if !key_part.is_empty() {
            return Ok(RequestItem::HttpHeader { key: unescape_key(key_part), value: "".to_string() });
        }
    }
    Err(format!("Invalid value for '[REQUEST_ITEM]...': {:?}", item))
}

#[derive(Debug)]
struct FormatOptions {
    json_indent: Option<usize>,
    json_format: Option<bool>,
    headers_sort: Option<bool>,
}

fn parse_format_options(opts: &[String]) -> Result<FormatOptions, String> {
    let mut json_indent=None;
    let mut json_format=None;
    let mut headers_sort=None;
    for opt_str in opts {
        for part in opt_str.split(',') {
            if part.trim().is_empty() { continue; }
            let kv: Vec<&str>=part.splitn(2,':').collect();
            if kv.len()!=2 { return Err(format!("Invalid format option {}", part)); }
            let k=kv[0].trim();
            let v=kv[1].trim();
            match k {
                "json.indent" => { json_indent=Some(v.parse().map_err(|_| format!("Invalid indent"))?); },
                "json.format" => {
                    match v {
                        "true" => json_format=Some(true),
                        "false" => json_format=Some(false),
                        _ => return Err(format!("Invalid json.format")),
                    }
                },
                "headers.sort" => {
                    match v {
                        "true" => headers_sort=Some(true),
                        "false" => headers_sort=Some(false),
                        _ => return Err(format!("Invalid headers.sort")),
                    }
                },
                _ => return Err(format!("Unknown format option {}", k)),
            }
        }
    }
    Ok(FormatOptions { json_indent, json_format, headers_sort })
}

fn is_method_token(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c.is_ascii_alphabetic())
}

fn is_url_like(s: &str) -> bool {
    if s.contains("://") { return true; }
    if s.starts_with(':') { return true; }
    if s.contains('/') { return true; }
    if s.contains('@') { return true; }
    if s.contains('.') { return true; }
    if s.contains(';') { return true; }
    if s.contains('=') { return true; }
    if s.contains(':') { return true; }
    false
}

fn is_url_like_for_second(_s: &str) -> bool { true }

fn parse_url_custom(input: &str, default_scheme: &str) -> Result<url::Url, String> {
    let mut url_str = input.to_string();
    if url_str.starts_with("://") {
        let scheme = if default_scheme.is_empty() { "http" } else { default_scheme };
        url_str = format!("{}://{}", scheme, &url_str[3..]);
    } else if url_str.starts_with(':') {
        let scheme = if default_scheme.is_empty() { "http" } else { default_scheme };
        if url_str.len()>=2 && url_str.chars().nth(1)==Some('/') {
            url_str = format!("{}://localhost{}", scheme, &url_str[1..]);
        } else {
            if let Some(slash_idx) = url_str.find('/') {
                let port_part = &url_str[..slash_idx];
                let path_part = &url_str[slash_idx..];
                url_str = format!("{}://localhost{}{}", scheme, port_part, path_part);
            } else {
                url_str = format!("{}://localhost{}", scheme, url_str);
            }
        }
    } else if !url_str.contains("://") {
        let scheme = if default_scheme.is_empty() { "http" } else { default_scheme };
        url_str = format!("{}://{}", scheme, url_str);
    }
    url::Url::parse(&url_str).map_err(|e| {
        let err_str = e.to_string();
        if err_str.contains("invalid port") {
            "Invalid <URL>: invalid port number".to_string()
        } else {
            format!("Invalid <URL>: {}", err_str)
        }
    })
}

