#[derive(Debug, Clone)]
enum PathPart {
    Key(String),
    Index(usize),
    Append,
}

fn insert_path(root: &mut serde_json::Value, path: &[PathPart], value: serde_json::Value) {
    if path.is_empty() { *root=value; return; }
    let mut cur=root;
    for (i, part) in path.iter().enumerate() {
        let is_last=i==path.len()-1;
        match part {
            PathPart::Key(k) => {
                if is_last {
                    if let serde_json::Value::Object(map)=cur {
                        map.insert(k.clone(), value.clone());
                    } else {
                        *cur=serde_json::Value::Object({
                            let mut m=serde_json::Map::new();
                            m.insert(k.clone(), value.clone());
                            m
                        });
                    }
                    break;
                } else {
                    let next_is_array=matches!(path.get(i+1), Some(PathPart::Index(_)) | Some(PathPart::Append));
                    if let serde_json::Value::Object(map)=cur {
                        if !map.contains_key(k) {
                            if next_is_array { map.insert(k.clone(), serde_json::Value::Array(vec![])); } else { map.insert(k.clone(), serde_json::Value::Object(serde_json::Map::new())); }
                        }
                        cur=map.get_mut(k).unwrap();
                    } else {
                        *cur=serde_json::Value::Object(serde_json::Map::new());
                        if let serde_json::Value::Object(map)=cur {
                            if next_is_array { map.insert(k.clone(), serde_json::Value::Array(vec![])); } else { map.insert(k.clone(), serde_json::Value::Object(serde_json::Map::new())); }
                            cur=map.get_mut(k).unwrap();
                        }
                    }
                }
            },
            PathPart::Index(idx) => {
                if is_last {
                    if let serde_json::Value::Array(arr)=cur {
                        while arr.len()<=*idx { arr.push(serde_json::Value::Null); }
                        arr[*idx]=value.clone();
                    } else {
                        *cur=serde_json::Value::Array(vec![]);
                        if let serde_json::Value::Array(arr)=cur {
                            while arr.len()<=*idx { arr.push(serde_json::Value::Null); }
                            arr[*idx]=value.clone();
                        }
                    }
                    break;
                } else {
                    if let serde_json::Value::Array(arr)=cur {
                        while arr.len()<=*idx { arr.push(serde_json::Value::Null); }
                        let next_is_array=matches!(path.get(i+1), Some(PathPart::Index(_)) | Some(PathPart::Append));
                        if arr[*idx].is_null() {
                            if next_is_array { arr[*idx]=serde_json::Value::Array(vec![]); } else { arr[*idx]=serde_json::Value::Object(serde_json::Map::new()); }
                        }
                        cur=&mut arr[*idx];
                    } else {
                        *cur=serde_json::Value::Array(vec![]);
                        if let serde_json::Value::Array(arr)=cur {
                            while arr.len()<=*idx { arr.push(serde_json::Value::Null); }
                            let next_is_array=matches!(path.get(i+1), Some(PathPart::Index(_)) | Some(PathPart::Append));
                            if next_is_array { arr[*idx]=serde_json::Value::Array(vec![]); } else { arr[*idx]=serde_json::Value::Object(serde_json::Map::new()); }
                            cur=&mut arr[*idx];
                        }
                    }
                }
            },
            PathPart::Append => {
                if is_last {
                    if let serde_json::Value::Array(arr)=cur {
                        arr.push(value.clone());
                    } else {
                        *cur=serde_json::Value::Array(vec![value.clone()]);
                    }
                    break;
                } else {
                    let next_is_array=matches!(path.get(i+1), Some(PathPart::Index(_)) | Some(PathPart::Append));
                    if let serde_json::Value::Array(arr)=cur {
                        if next_is_array { arr.push(serde_json::Value::Array(vec![])); } else { arr.push(serde_json::Value::Object(serde_json::Map::new())); }
                        let len=arr.len();
                        cur=&mut arr[len-1];
                    } else {
                        *cur=serde_json::Value::Array(vec![]);
                        if let serde_json::Value::Array(arr)=cur {
                            if next_is_array { arr.push(serde_json::Value::Array(vec![])); } else { arr.push(serde_json::Value::Object(serde_json::Map::new())); }
                            let len=arr.len();
                            cur=&mut arr[len-1];
                        }
                    }
                }
            },
        }
    }
}

fn build_json_from_data(fields: Vec<(String, serde_json::Value)>) -> serde_json::Value {
    let mut root=serde_json::Value::Object(serde_json::Map::new());
    for (raw_key,val) in fields {
        let mut path_parts: Vec<PathPart>=Vec::new();
        let mut current=String::new();
        let mut chars=raw_key.chars().peekable();
        while let Some(&c)=chars.peek() {
            if c=='[' {
                if !current.is_empty() { path_parts.push(PathPart::Key(current.clone())); current.clear(); }
                chars.next();
                let mut inner=String::new();
                while let Some(ch)=chars.next() { if ch==']' { break; } else { inner.push(ch); } }
                if inner.is_empty() { path_parts.push(PathPart::Append); }
                else if let Ok(idx)=inner.parse::<usize>() { path_parts.push(PathPart::Index(idx)); }
                else { path_parts.push(PathPart::Key(inner)); }
            } else { current.push(c); chars.next(); }
        }
        if !current.is_empty() { path_parts.push(PathPart::Key(current)); }
        insert_path(&mut root, &path_parts, val);
    }
    root
}

fn generate_boundary() -> String {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash,Hasher};
    use std::time::{SystemTime,UNIX_EPOCH};
    let mut hasher=DefaultHasher::new();
    SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos().hash(&mut hasher);
    std::process::id().hash(&mut hasher);
    let mut rng=hasher.finish();
    let mut parts=Vec::new();
    for _ in 0..4 {
        rng=rng.wrapping_mul(6364136223846793005).wrapping_add(1);
        parts.push(format!("{:016x}", rng));
    }
    parts.join("-")
}

fn shell_quote(s: &str) -> String {
    if s.is_empty() { return "''".to_string(); }
    if s.contains('\'') {
        let esc=s.replace('\'', "'\\''");
        format!("'{}'", esc)
    } else {
        format!("'{}'", s)
    }
}

