    for _ in range(4):
        parts.append(''.join(random.choice('0123456789abcdef') for _ in range(16)))
    return '-'.join(parts)

def shell_quote(s):
    if s=='':
        return "''"
    if "'" in s:
        return "'" + s.replace("'", "'\\''") + "'"
    else:
        return f"'{s}'"

