            return ('data_field_file', unescape(key), key, val[1:])
        else:
            return ('data_field', unescape(key), key, unescape(val))
    pos=find_unescaped(item, '@')
    if pos!=-1 and pos>0:
        key=item[:pos]
        spec=item[pos+1:]
        file_name,file_type,file_name_header=parse_file_spec(spec)
        return ('form_file', unescape(key), file_name, file_type, file_name_header)
    pos=find_unescaped(item, ':')
    if pos!=-1:
        key=item[:pos]
        val=item[pos+1:]
        k=unescape(key)
        # validate header name
        if not k or any(c.isspace() or c==':' or ord(c)<32 for c in k):
            # will be caught later as invalid header name, but for parsing we allow
            pass
        if val=='':
            return ('header_unset', k)
        if val.startswith('@'):
            return ('header_file', k, val[1:])
        return ('header', k, unescape(val))
    if item.endswith(';'):
        key=item[:-1]
        if key:
            return ('header', unescape(key), "")
    raise ValueError(f"Invalid value for '[REQUEST_ITEM]...': {item!r}")

def insert_path(root, raw_key, value):
    # parse raw_key into parts
    parts=[]
    cur=""
    i=0
    while i < len(raw_key):
        c=raw_key[i]
        if c=='[':
            if cur:
                parts.append(('key', cur))
                cur=""
            j=raw_key.find(']', i)
            if j==-1:
                # malformed, treat as key
                cur+=c
                i+=1
                continue
            inner=raw_key[i+1:j]
            if inner=='':
                parts.append(('append', None))
            else:
                try:
                    idx=int(inner)
                    parts.append(('index', idx))
                except:
                    parts.append(('key', inner))
            i=j+1
        else:
            cur+=c
            i+=1
    if cur:
        parts.append(('key', cur))

    cur_root=root
    for idx,(typ,val) in enumerate(parts):
        is_last=idx==len(parts)-1
        if typ=='key':
            k=val
            if is_last:
                cur_root[k]=value
                break
            else:
                next_is_array = idx+1 < len(parts) and parts[idx+1][0] in ('index','append')
                if k not in cur_root or not isinstance(cur_root[k], (dict, list)):
                    cur_root[k]=[] if next_is_array else {}
                cur_root=cur_root[k]
        elif typ=='index':
            index=val
            if is_last:
                if not isinstance(cur_root, list):
                    cur_root=[] # should not happen, but override?
                while len(cur_root)<=index:
                    cur_root.append(None)
                cur_root[index]=value
                break
            else:
                if not isinstance(cur_root, list):
                    # make list? But we are inside key handling that should have made list
                    cur_root=[]
                while len(cur_root)<=index:
                    cur_root.append(None)
                next_is_array = idx+1 < len(parts) and parts[idx+1][0] in ('index','append')
                if cur_root[index] is None:
                    cur_root[index]=[] if next_is_array else {}
                cur_root=cur_root[index]
        elif typ=='append':
            if is_last:
                if not isinstance(cur_root, list):
                    # if cur_root is not list, make list
                    # This case happens when root["a"] is list, cur_root is that list
                    if isinstance(cur_root, list):
                        cur_root.append(value)
                    else:
                        # convert to list
                        cur_root=[value]
                else:
                    cur_root.append(value)
                break
            else:
                next_is_array = idx+1 < len(parts) and parts[idx+1][0] in ('index','append')
                if not isinstance(cur_root, list):
                    cur_root=[]
                if next_is_array:
                    cur_root.append([])
                else:
                    cur_root.append({})
                cur_root=cur_root[-1]

def build_json(fields):
    root={}
    for raw_key,val in fields:
        # val is already JSON or string
        insert_path(root, raw_key, val)
    return root

def generate_boundary():
    # generate 4 parts hex 16 chars each
    parts=[]
    for _ in range(4):
        parts.append(''.join(random.choice('0123456789abcdef') for _ in range(16)))
    return '-'.join(parts)

def shell_quote(s):
    if s=='':
        return "''"
    if "'" in s:
        return "'" + s.replace("'", "'\\''") + "'"
    else:
        return f"'{s}'"

