            i+=2
            continue
        if s[i:i+len(pat)]==pat:
            return i
        i+=1
    return -1

def unescape(s):
    res=[]
    i=0
    while i < len(s):
        if s[i]=='\\' and i+1 < len(s):
            res.append(s[i+1])
            i+=2
        else:
            res.append(s[i])
            i+=1
    return ''.join(res)

def parse_file_spec(spec):
    parts=spec.split(';')
    file_name=parts[0]
    ft=None
    fnh=None
    for part in parts[1:]:
        if part.startswith('type='):
            ft=part[5:]
        elif part.startswith('filename='):
            fnh=part[9:]
    return file_name, ft, fnh

def parse_request_item(item):
    if item.startswith('@'):
        rest=item[1:]
        fn,ft,_=parse_file_spec(rest)
        return ('body_file', fn, ft)
    pos=find_unescaped(item, '==')
    if pos!=-1:
        key=item[:pos]
        val=item[pos+2:]
        k=unescape(key)
        if val.startswith('@'):
            return ('url_param_file', k, val[1:])
        else:
            return ('url_param', k, unescape(val))
    pos=find_unescaped(item, ':=')
    if pos!=-1:
        key=item[:pos]
        val=item[pos+2:]
        raw_key=key
        k=unescape(key)
        if val.startswith('@'):
            try:
                content=open(val[1:],'r').read()
                j=json.loads(content)
            except FileNotFoundError:
                raise FileNotFoundError("No such file or directory (os error 2)")
            except Exception as e:
                raise ValueError(f"Invalid value for '[REQUEST_ITEM]...': {item!r} {e}")
            return ('json_field', k, raw_key, j)
        else:
            try:
                j=json.loads(val)
            except Exception:
                raise ValueError(f"Invalid value for '[REQUEST_ITEM]...': {item!r} expected value at line 1 column 1")
            return ('json_field', k, raw_key, j)
    pos=find_unescaped(item, '=')
    if pos!=-1:
        key=item[:pos]
        val=item[pos+1:]
        if val.startswith('@'):
            return ('data_field_file', unescape(key), key, val[1:])
        else:
            return ('data_field', unescape(key), key, unescape(val))
    pos=find_unescaped(item, '@')
    if pos!=-1 and pos>0:
        key=item[:pos]
        spec=item[pos+1:]
        fn,ft,fnh=parse_file_spec(spec)
        return ('form_file', unescape(key), fn, ft, fnh)
    pos=find_unescaped(item, ':')
    if pos!=-1:
        key=item[:pos]
        val=item[pos+1:]
        k=unescape(key)
        if val=='':
            return ('header_unset', k)
        if val.startswith('@'):
            return ('header_file', k, val[1:])
        return ('header', k, unescape(val))
    if item.endswith(';'):
        key=item[:-1]
        if key:
            return ('header', unescape(key), "")
    raise ValueError(f"Invalid value for '[REQUEST_ITEM]...': {item!r}")

def insert_path(root, raw_key, value):
    parts=[]
    cur=""
    i=0
    while i < len(raw_key):
        c=raw_key[i]
        if c=='[':
            if cur:
                parts.append(('key', cur))
                cur=""
            j=raw_key.find(']', i)
            if j==-1:
                cur+=c
                i+=1
                continue
            inner=raw_key[i+1:j]
            if inner=='':
                parts.append(('append', None))
            else:
                try:
                    idx=int(inner)
                    parts.append(('index', idx))
                except:
                    parts.append(('key', inner))
            i=j+1
        else:
            cur+=c
            i+=1
    if cur:
        parts.append(('key', cur))

    cur_root=root
    for idx,(typ,val) in enumerate(parts):
        is_last=idx==len(parts)-1
        if typ=='key':
            k=val
            if is_last:
                cur_root[k]=value
                break
            else:
                next_is_array = idx+1 < len(parts) and parts[idx+1][0] in ('index','append')
                if k not in cur_root or not isinstance(cur_root[k], (dict, list)):
                    cur_root[k]=[] if next_is_array else {}
                cur_root=cur_root[k]
        elif typ=='index':
            index=val
            if is_last:
                if not isinstance(cur_root, list):
                    cur_root=[]
                while len(cur_root)<=index:
                    cur_root.append(None)
                cur_root[index]=value
                break
            else:
                if not isinstance(cur_root, list):
                    cur_root=[]
                while len(cur_root)<=index:
                    cur_root.append(None)
                next_is_array = idx+1 < len(parts) and parts[idx+1][0] in ('index','append')
                if cur_root[index] is None:
                    cur_root[index]=[] if next_is_array else {}
                cur_root=cur_root[index]
        elif typ=='append':
            if is_last:
                if isinstance(cur_root, list):
                    cur_root.append(value)
                else:
                    # if not list, make list
                    # This case for root["a"] being list
                    if isinstance(cur_root, dict):
                        # we are at root["a"] which is list, but cur_root is that list
                        pass
                    cur_root=[value]
                break
            else:
                next_is_array = idx+1 < len(parts) and parts[idx+1][0] in ('index','append')
                if not isinstance(cur_root, list):
                    cur_root=[]
                if next_is_array:
                    cur_root.append([])
                else:
                    cur_root.append({})
                cur_root=cur_root[-1]

def build_json(fields):
    root={}
    for raw_key,val in fields:
        insert_path(root, raw_key, val)
    return root

def generate_boundary():
    parts=[]
    for _ in range(4):
        parts.append(''.join(random.choice('0123456789abcdef') for _ in range(16)))
    return '-'.join(parts)

def shell_quote(s):
    if s=='':
        return "''"
    if "'" in s:
        return "'" + s.replace("'", "'\\''") + "'"
    else:
        return f"'{s}'"

