    # proxy list
    proxy_list=[]
    for idx,arg in enumerate(args):
        if arg=="--proxy" and idx+1 < len(args):
            proxy_list.append(args[idx+1])
        elif arg.startswith("--proxy="):
            proxy_list.append(arg.split("=",1)[1])

    for pv in proxy_list:
        if ':' not in pv:
            print(f"error: invalid value '{pv}' for '--proxy <PROTOCOL:URL>': Invalid proxy URL '' for protocol '{pv}': relative URL without a base\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        proto,url_part = pv.split(':',1)
        try:
            # url_part must be absolute URL with scheme
            p=urllib.parse.urlparse(url_part)
            if not p.scheme or not p.netloc:
                raise ValueError()
            if url_part.startswith('//'):
                raise ValueError()
        except:
            print(f"error: invalid value '{pv}' for '--proxy <PROTOCOL:URL>': Invalid proxy URL '{url_part}' for protocol '{proto}': relative URL without a base\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)

    if not positional:
        print(f"error: the following required arguments were not provided:\n  <[METHOD] URL>\n\nUsage: {bin_name} --offline --ignore-stdin <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
        sys.exit(2)

    method=None
    url_str=None
    req_items=[]
    if len(positional)>=2:
        first=positional[0]
        second=positional[1]
        if is_method_token(first):
            try:
                u_str,parsed = parse_url_custom(second, default_scheme)
                method=first.upper()
                url_str=second
                req_items=positional[2:]
            except ValueError as e:
                if "invalid port" in str(e):
                    print(f"error: {e}", file=sys.stderr)
                    sys.exit(2)
                else:
                    url_str=first
                    req_items=positional[1:]
        else:
            url_str=first
            req_items=positional[1:]
    else:
        first=positional[0]
        try:
            u_str,parsed = parse_url_custom(first, default_scheme)
            url_str=first
        except ValueError as e:
            if "invalid port" in str(e):
                print(f"error: {e}", file=sys.stderr)
                sys.exit(2)
            else:
                print(f"error: Missing <URL>\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)

    try:
        url_final_str, url_parsed = parse_url_custom(url_str, default_scheme)
        final_url = urllib.parse.urlparse(url_final_str)
    except ValueError as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(2)

    items=[]
    for s in req_items:
        try:
            it=parse_request_item(s)
            items.append(it)
        except FileNotFoundError:
            print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
            sys.exit(1)
        except ValueError as e:
            msg=str(e)
            if "Invalid value" in msg:
                print(f"error: {msg}\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)
            else:
                print(f"error: {msg}", file=sys.stderr)
                sys.exit(2)

    body_type="json"
    for a in sys.argv:
        if a in ("--json","-j"):
            body_type="json"
        elif a in ("--form","-f"):
            body_type="form"
        elif a=="--multipart":
            body_type="multipart"

    has_data=False
    has_form_files=False
    has_body_file=False
    for it in items:
        if it[0] in ('data_field','data_field_file','json_field'):
            has_data=True
        elif it[0]=='form_file':
            if it[1]=='':
                has_body_file=True
            else:
                has_form_files=True
        elif it[0]=='body_file':
            has_body_file=True

    raw_opt_val = parsed.get("--raw")
    if raw_opt_val:
        if has_data or has_form_files:
            print(f"error: Request body (from --raw) and request data (key=value) cannot be mixed.\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        if has_body_file:
            print(f"error: Request body (from --raw) and request data (key=value) cannot be mixed.\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)

    if has_body_file and (has_data or has_form_files):
        print(f"{bin_name}: error: Request body (from a file) and request data (key=value) cannot be mixed.", file=sys.stderr)
        sys.exit(1)

    if body_type=="json" and has_form_files:
        print(f"{bin_name}: error: Can't use file fields in JSON mode (perhaps you meant --form?)", file=sys.stderr)
        sys.exit(1)

    stdin_content=None
    if not (parsed.get("--ignore-stdin") or parsed.get("-I")):
        if not sys.stdin.isatty():
            try:
                data=sys.stdin.read()
                stdin_content=data
            except:
                stdin_content=None

    if not (parsed.get("--ignore-stdin") or parsed.get("-I")):
        # if stdin not tty and data present, error (even empty?)
        if not sys.stdin.isatty():
            # if we have data fields etc, error
            if has_data or has_form_files or has_body_file or raw_opt_val:
                print(f"{bin_name}: error: Request body (from stdin) and request data (key=value) cannot be mixed. Pass --ignore-stdin to ignore standard input.", file=sys.stderr)
                sys.exit(1)

    final_method = method if method else ("POST" if (has_data or has_form_files or has_body_file or raw_opt_val or stdin_content is not None) else "GET")

    # query
    query_pairs=list(urllib.parse.parse_qsl(final_url.query))
    for it in items:
        if it[0]=='url_param':
            _,k,v = it
            query_pairs.append((k,v))
        elif it[0]=='url_param_file':
            _,k,fp = it
            try:
                content=open(fp,'r').read()
            except:
                print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                sys.exit(1)
            query_pairs.append((k, content.strip()))

    if query_pairs:
        q_str=urllib.parse.urlencode(query_pairs, doseq=True)
        final_url=final_url._replace(query=q_str)

    final_url_str=urllib.parse.urlunparse(final_url)
    path=final_url.path if final_url.path else "/"
    query=f"?{final_url.query}" if final_url.query else ""
    request_line=f"{final_method} {path}{query} HTTP/1.1"

    fmt_opts={}
    # collect format-options from args
    for idx,arg in enumerate(args):
        if arg=="--format-options" and idx+1 < len(args):
            for part in args[idx+1].split(','):
                if ':' in part:
                    k,v=part.split(':',1)
                    fmt_opts[k.strip()]=v.strip()
        elif arg.startswith("--format-options="):
            val=arg.split("=",1)[1]
            for part in val.split(','):
                if ':' in part:
                    k,v=part.split(':',1)
                    fmt_opts[k.strip()]=v.strip()

    pretty_val = parsed.get("--pretty")
    if not pretty_val:
        if not sys.stdout.isatty():
            pretty_val="none"
        else:
            if os.environ.get("NO_COLOR"):
                pretty_val="format"
            else:
                term=os.environ.get("TERM","")
                if term and term!="dumb":
                    pretty_val="all"
                else:
                    pretty_val="format"

    headers_sort=False
    if "headers.sort" in fmt_opts:
        headers_sort=fmt_opts["headers.sort"]=="true"
    else:
        headers_sort=pretty_val in ("format","all")

    json_format=False
    if "json.format" in fmt_opts:
        json_format=fmt_opts["json.format"]=="true"
    else:
        json_format=pretty_val in ("format","all")

    json_indent=4
    if "json.indent" in fmt_opts:
        try:
            json_indent=int(fmt_opts["json.indent"])
        except:
            pass

    body_str=None
    content_type=None
    is_multipart=False

    if raw_opt_val:
        body_str=raw_opt_val
        content_type="application/json"
    elif has_body_file:
        for it in items:
            if it[0]=='body_file':
                _,fn,ft = it
                ft=ft or guess_mime(fn)
                content_type=ft
                try:
                    body_str=open(fn,'r', errors='ignore').read()
                except:
                    print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                    sys.exit(1)
                break
            elif it[0]=='form_file' and it[1]=='':
                # empty key body file via form_file?
                # it is ('form_file', key, file_name, file_type, file_name_header)
                _,key,fn,ft,fnh = it
                ft=ft or guess_mime(fn)
                content_type=ft
                try:
                    body_str=open(fn,'r', errors='ignore').read()
                except:
                    print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                    sys.exit(1)
                break
    elif stdin_content is not None:
        body_str=stdin_content if stdin_content!='' else ""
        if stdin_content=='':
            body_str=""
        content_type="application/json"
    elif body_type=="json" and has_data:
        fields=[]
        for it in items:
            if it[0]=='data_field':
                _,k,rawk,v = it
                fields.append((rawk, v))
            elif it[0]=='data_field_file':
                _,k,rawk,fp = it
                try:
                    content=open(fp,'r').read()
                except:
                    print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                    sys.exit(1)
                fields.append((rawk, content))
            elif it[0]=='json_field':
                _,k,rawk,jv = it
                fields.append((rawk, jv))
        root={}
        for rawk,val in fields:
            insert_path(root, rawk, val)
        if json_format:
            if json_indent==2:
                body_str=json.dumps(root, indent=2)
            else:
                body_str=json.dumps(root, indent=4)
        else:
            body_str=json.dumps(root)
        content_type="application/json"
    elif body_type=="form":
        if has_form_files:
            is_multipart=True
            boundary=generate_boundary()
            content_type=f"multipart/form-data; boundary={boundary}"
            mp=[]
            for it in items:
                if it[0]=='data_field':
                    _,k,rawk,v = it
                    mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{v}\r\n")
                elif it[0]=='data_field_file':
                    _,k,rawk,fp = it
                    try:
                        content=open(fp,'r').read()
                    except:
                        print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                        sys.exit(1)
                    mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{content}\r\n")
                elif it[0]=='form_file':
                    _,k,fn,ft,fnh = it
                    if k=='':
                        continue
                    filename = fnh or os.path.basename(fn)
                    file_content = open(fn,'r', errors='ignore').read()
                    if ft:
                        mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"; filename=\"{filename}\"\r\nContent-Type: {ft}\r\n\r\n{file_content}\r\n")
                    else:
                        mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"; filename=\"{filename}\"\r\n\r\n{file_content}\r\n")
            mp.append(f"--{boundary}--\r\n")
            body_str=''.join(mp)
        else:
            pairs=[]
            for it in items:
                if it[0]=='data_field':
                    _,k,rawk,v = it
                    pairs.append((k,v))
                elif it[0]=='data_field_file':
                    _,k,rawk,fp = it
                    try:
                        content=open(fp,'r').read()
                    except:
                        print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                        sys.exit(1)
                    pairs.append((k, content.strip()))
                elif it[0]=='json_field':
                    _,k,rawk,jv = it
                    pairs.append((k, str(jv)))
            body_str=urllib.parse.urlencode(pairs, doseq=True)
            content_type="application/x-www-form-urlencoded"
    elif body_type=="multipart":
        is_multipart=True
        boundary=generate_boundary()
        content_type=f"multipart/form-data; boundary={boundary}"
        mp=[]
        for it in items:
            if it[0]=='data_field':
                _,k,rawk,v = it
                mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{v}\r\n")
            elif it[0]=='data_field_file':
                _,k,rawk,fp = it
                try:
                    content=open(fp,'r').read()
                except:
                    print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                    sys.exit(1)
                mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{content}\r\n")
            elif it[0]=='form_file':
                _,k,fn,ft,fnh = it
                if k=='':
                    continue
                filename = fnh or os.path.basename(fn)
                file_content = open(fn,'r', errors='ignore').read()
                if ft:
                    mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"; filename=\"{filename}\"\r\nContent-Type: {ft}\r\n\r\n{file_content}\r\n")
                else:
                    mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"; filename=\"{filename}\"\r\n\r\n{file_content}\r\n")
        mp.append(f"--{boundary}--\r\n")
        body_str=''.join(mp)

    # headers
    custom_headers_ordered=[]
    headers_to_unset=[]
    has_content_encoding_custom=False
    for it in items:
        if it[0]=='header':
            _,k,v = it
            if not is_valid_header_name(k):
                print(f"{bin_name}: error: invalid HTTP header name", file=sys.stderr)
                sys.exit(1)
            if k.lower()=="content-encoding":
                has_content_encoding_custom=True
            custom_headers_ordered.append((k,v))
        elif it[0]=='header_file':
            _,k,fp = it
            if not is_valid_header_name(k):
                print(f"{bin_name}: error: invalid HTTP header name", file=sys.stderr)
                sys.exit(1)
            try:
                content=open(fp,'r').read()
            except:
                print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                sys.exit(1)
            if k.lower()=="content-encoding":
                has_content_encoding_custom=True
            custom_headers_ordered.append((k, content.strip()))
        elif it[0]=='header_unset':
            _,k = it
            headers_to_unset.append(k.lower())

    def find_last(name):
        lname=name.lower()
        for k,v in reversed(custom_headers_ordered):
            if k.lower()==lname:
                return v
        return None

    def has_custom_header(name):
        lname=name.lower()
        return any(k.lower()==lname for k,v in custom_headers_ordered)

    headers=[]
    accept_enc_default = "identity" if download else "gzip, deflate, br, zstd"
    user_agent_default = f"xh/{VERSION}"
    connection_default = "keep-alive"

    if "accept-encoding" not in headers_to_unset:
        v=find_last("accept-encoding")
        headers.append(("Accept-Encoding", v if v else accept_enc_default))
    if "user-agent" not in headers_to_unset:
        v=find_last("user-agent")
        headers.append(("User-Agent", v if v else user_agent_default))
    if "connection" not in headers_to_unset:
        v=find_last("connection")
        headers.append(("Connection", v if v else connection_default))

    auth_header=None
    if bearer:
        auth_header=("Authorization", f"Bearer {bearer}")
    elif auth:
        at = auth_type if auth_type else "basic"
        if at=="bearer":
            auth_header=("Authorization", f"Bearer {auth}")
        elif at=="basic":
            enc=base64.b64encode(auth.encode()).decode()
            auth_header=("Authorization", f"Basic {enc}")

    is_get_like = not (body_str is not None) and final_method=="GET"

    if is_get_like:
        if auth_header and "authorization" not in headers_to_unset and not has_custom_header("authorization"):
            headers.append(auth_header)
        remaining=[]
        for k,v in custom_headers_ordered:
            kl=k.lower()
            if kl in ("accept-encoding","user-agent","connection","authorization"):
                continue
            if kl in headers_to_unset:
                continue
            remaining.append((k,v))
        seen=set()
        dedup=[]
        for k,v in reversed(remaining):
            kl=k.lower()
            if kl in seen:
                continue
            seen.add(kl)
            dedup.append((k,v))
        dedup.reverse()
        headers.extend(dedup)

        if not has_custom_header("accept") and "accept" not in headers_to_unset:
            headers.append(("Accept","*/*"))
        if not has_custom_header("host") and "host" not in headers_to_unset:
            host = final_url.hostname or ""
            port = final_url.port
            host_h = f"{host}:{port}" if port else host
            headers.append(("Host", host_h))
    else:
        is_file_or_form = has_body_file or body_type in ("form","multipart")
        if is_file_or_form:
            if body_str is not None and "content-type" not in headers_to_unset:
                v=find_last("content-type")
                if v:
                    headers.append(("Content-Type", v))
                elif content_type:
                    headers.append(("Content-Type", content_type))
            if "accept" not in headers_to_unset:
                v=find_last("accept")
                if v:
                    headers.append(("Accept", v))
                else:
                    acc = "*/*" if body_type in ("form","multipart") or has_body_file else "application/json, */*;q=0.5"
                    headers.append(("Accept", acc))
        else:
            if "accept" not in headers_to_unset:
                v=find_last("accept")
                if v:
                    headers.append(("Accept", v))
                else:
                    acc = "*/*" if body_type in ("form","multipart") or has_body_file else "application/json, */*;q=0.5"
                    headers.append(("Accept", acc))
            if body_str is not None and "content-type" not in headers_to_unset:
                v=find_last("content-type")
                if v:
                    headers.append(("Content-Type", v))
                elif content_type:
                    headers.append(("Content-Type", content_type))

        if auth_header and "authorization" not in headers_to_unset and not has_custom_header("authorization"):
            headers.append(auth_header)

        remaining=[]
        for k,v in custom_headers_ordered:
            kl=k.lower()
            if kl in ("accept-encoding","user-agent","connection","accept","content-type","authorization","content-length"):
                continue
            if kl in headers_to_unset:
                continue
            remaining.append((k,v))
        seen=set()
        dedup=[]
        for k,v in reversed(remaining):
            kl=k.lower()
            if kl in seen:
                continue
            seen.add(kl)
            dedup.append((k,v))
        dedup.reverse()
        headers.extend(dedup)

        if body_str is not None and not is_multipart and not has_body_file and "content-length" not in headers_to_unset:
            headers.append(("Content-Length", str(len(body_str))))

        if not has_custom_header("host") and "host" not in headers_to_unset:
            host = final_url.hostname or ""
            port = final_url.port
            host_h = f"{host}:{port}" if port else host
            headers.append(("Host", host_h))

    if compress and has_content_encoding_custom:
        print(f"{bin_name}: warning: --compress can't be used with a 'Content-Encoding:' header. --compress will be disabled.", file=sys.stderr)

    if headers_sort:
        headers.sort(key=lambda x: x[0].lower())

    print_opt_val = parsed.get("--print") or parsed.get("-p")
    if "--headers" in parsed or "-h" in parsed:
        print_opt_val="h"
    if "--body" in parsed or "-b" in parsed:
        print_opt_val="b"
    if "--meta" in parsed or "-m" in parsed:
        print_opt_val="m"
    if verbose and not print_opt_val:
        print_opt_val="HB"

    print_str = print_opt_val if print_opt_val else ("HB" if body_str is not None else "H")

    # curl
    curl_flag = "--curl" in parsed or parsed.get("--curl") or "-c" in parsed and False
    # Actually check
    is_curl = "--curl" in sys.argv or "--curl" in parsed
    if "--curl" in parsed or parsed.get("--curl") or "--curl" in args:
        is_curl=True
    else:
        is_curl=False
    if "--curl" in sys.argv:
        is_curl=True

    if is_curl:
        if offline:
            print("Warning: Ignored --offline", file=sys.stderr)
        warnings=[]
        if print_opt or headers_flag or body_flag or meta_flag:
            warnings.append("-p/--print")
        if body_flag:
            warnings.append("-b/--body")
        if pretty_opt:
            warnings.append("--pretty")
        if style_opt:
            warnings.append("-s/--style")
        if response_charset:
            warnings.append("--response-charset")
        if response_mime:
            warnings.append("--response-mime")
        if session:
            warnings.append("--session")
        if session_read_only:
            warnings.append("--session-read-only")
        if history_print:
            warnings.append("-P/--history-print")
        if all:
            warnings.append("--all")
        if verbose and "--all" not in warnings:
            warnings.append("--all")
        for w in warnings:
            print(f"Warning: Ignored {w}", file=sys.stderr)

        explicit = method is not None
        parts=["curl"]
        if follow:
            parts.append("-L")
        if download and not output:
            parts.extend(["-f","-L","-O"])

        if explicit:
            if "--curl-long" in sys.argv:
                parts.append("--request")
            else:
                parts.append("-X")
            parts.append(final_method)

        url_c = final_url_str
        if '?' in url_c or '&' in url_c or ' ' in url_c or "'" in url_c:
            url_c = "'" + url_c.replace("'", "'\\''") + "'"
        parts.append(url_c)

        if auth:
            at = auth_type if auth_type else "basic"
            if at=="basic":
                if "--curl-long" in sys.argv:
                    parts.extend(["--basic","--user"])
                else:
                    parts.extend(["--basic","-u"])
                parts.append(auth)
            elif at=="digest":
                if "--curl-long" in sys.argv:
                    parts.extend(["--digest","--user"])
                else:
                    parts.extend(["--digest","-u"])
                parts.append(auth)
            elif at=="bearer":
                parts.extend(["--oauth2-bearer", auth])
        elif bearer:
            parts.extend(["--oauth2-bearer", bearer])

        if verify and verify in ("no","false"):
            parts.append("--insecure" if "--curl-long" in sys.argv else "-k")

        curl_headers=[]
        include_ct = not (body_type=="form" and not is_multipart)
        if include_ct:
            for k,v in headers:
                if k.lower()=="content-type" and not is_multipart:
                    curl_headers.append((k.lower(), v))
                    break
        for k,v in headers:
            if k.lower()=="accept" and v!="*/*":
                curl_headers.append((k.lower(), v))
                break
        for k,v in custom_headers_ordered:
            kl=k.lower()
            if kl in ("host","content-length","connection","accept-encoding","user-agent","content-type","accept","authorization"):
                continue
            curl_headers.append((kl, v))

        for k,v in curl_headers:
            hs = f"{k}: {v}" if v else f"{k}:"
            parts.append("--header" if "--curl-long" in sys.argv else "-H")
            parts.append(shell_quote(hs))

        if body_str is not None:
            if is_multipart:
                for it in items:
                    if it[0]=='data_field':
                        _,k,rawk,v = it
                        parts.append("--form" if "--curl-long" in sys.argv else "-F")
                        parts.append(shell_quote(f"{k}={v}"))
                    elif it[0]=='form_file':
                        _,k,fn,ft,fnh = it
                        spec=f"{k}=@{fn}"
                        if ft:
                            spec+=f";type={ft}"
                        if fnh:
                            spec+=f";filename={fnh}"
                        parts.append("--form" if "--curl-long" in sys.argv else "-F")
                        parts.append(shell_quote(spec))
            elif body_type=="form" and not is_multipart:
                for it in items:
                    if it[0]=='data_field':
                        _,k,rawk,v = it
                        parts.append("--data-urlencode")
                        parts.append(shell_quote(f"{k}={v}"))
                    elif it[0]=='data_field_file':
                        _,k,rawk,fp = it
                        try:
                            content=open(fp,'r').read().strip()
                        except:
                            content=""
                        parts.append("--data-urlencode")
                        parts.append(shell_quote(f"{k}={content}"))
            elif has_body_file:
                for it in items:
                    if it[0]=='body_file':
                        _,fn,ft = it
                        parts.append("--data-binary")
                        parts.append(f"@{fn}")
                    elif it[0]=='form_file' and it[1]=='':
                        _,k,fn,ft,fnh = it
