def find_unescaped(s, pat):
    i=0
    while i+len(pat) <= len(s):
        if s[i]=='\\':
            i+=2
            continue
        if s[i:i+len(pat)]==pat:
            return i
        i+=1
    return -1

def unescape(s):
    res=[]
    i=0
    while i < len(s):
        if s[i]=='\\' and i+1 < len(s):
            res.append(s[i+1])
            i+=2
        else:
