                        pass
                    cur_root=[value]
                break
            else:
                next_is_array = idx+1 < len(parts) and parts[idx+1][0] in ('index','append')
                if not isinstance(cur_root, list):
                    cur_root=[]
                if next_is_array:
                    cur_root.append([])
                else:
                    cur_root.append({})
                cur_root=cur_root[-1]

