                if a in ("-s","--style"):
                    parsed["--style"]=args[i+1]
                if a in ("-P","--history-print"):
                    parsed["--history-print"]=args[i+1]
                if a in ("-o","--output"):
                    parsed["--output"]=args[i+1]
                if a in ("-A","--auth-type"):
                    parsed["--auth-type"]=args[i+1]
                if a in ("-a","--auth"):
                    parsed["--auth"]=args[i+1]
                if a=="--format-options":
                    format_opts_list.append(args[i+1])
                if a=="--proxy":
                    proxies.append(args[i+1])
                if a=="--generate":
                    parsed["--generate"]=args[i+1]
                i+=1
            else:
                if i+1>=len(args):
                    # check if arg is --generate without = already handled? For --generate we need value
                    if a=="--generate":
                        print(f"error: a value is required for '--generate <KIND>' but none was supplied\n  [possible values: complete-bash, complete-elvish, complete-fish, complete-nushell, complete-powershell, complete-zsh, man]\n\nFor more information, try '--help'.", file=sys.stderr)
                        sys.exit(2)
                    print(f"error: a value is required for '{a}'", file=sys.stderr)
                    sys.exit(2)
                # validate timeout
                if a=="--timeout":
                    try:
                        float(args[i+1])
                    except:
                        print(f"error: invalid value '{args[i+1]}' for '--timeout <SEC>': Connection timeout is not a valid number\n\nFor more information, try '--help'.", file=sys.stderr)
                        sys.exit(2)
                if a=="--pretty":
                    val=args[i+1]
                    if val not in ("all","colors","format","none"):
                        print(f"error: invalid value '{val}' for '--pretty <STYLE>'\n  [possible values: all, colors, format, none]\n\nFor more information, try '--help'.", file=sys.stderr)
                        sys.exit(2)
                parsed[a]=args[i+1]
                if a=="--format-options":
                    format_opts_list.append(args[i+1])
                if a=="--proxy":
                    proxies.append(args[i+1])
                i+=1
        elif a in ("-j","--json","-f","--form","--multipart","-h","--headers","-b","--body","-m","--meta","--debug","--all","-S","--stream","-d","--download","-c","--continue","--ignore-netrc","--offline","--check-status","-F","--follow","--native-tls","--https","-4","--ipv4","-6","--ipv6","-I","--ignore-stdin","--curl","--curl-long","--help","-V","--version"):
            if a in ("-v","--verbose"):
                verbose+=1
                parsed["--verbose"]=verbose
            elif a in ("-q","--quiet"):
                quiet+=1
                parsed["--quiet"]=quiet
            elif a in ("-x","--compress"):
                compress+=1
                parsed["--compress"]=compress
            else:
                parsed[a]=True
        elif a.startswith("-") and len(a)==2:
            # single short
            if a in ("-j","-f","-h","-b","-m","-d","-c","-F","-4","-6","-I","-V","-S","-q","-x"):
                if a=="-v":
                    verbose+=1
                elif a=="-q":
                    quiet+=1
                elif a=="-x":
                    compress+=1
                else:
                    parsed[a]=True
            elif a in ("-s","-p","-P","-o","-A","-a"):
                if i+1>=len(args):
                    print(f"error: a value is required for '{a}'", file=sys.stderr)
                    sys.exit(2)
                parsed[a]=args[i+1]
                # map to long
                if a=="-s":
                    parsed["--style"]=args[i+1]
                if a=="-p":
                    parsed["--print"]=args[i+1]
                if a=="-P":
                    parsed["--history-print"]=args[i+1]
                if a=="-o":
                    parsed["--output"]=args[i+1]
                if a=="-A":
                    parsed["--auth-type"]=args[i+1]
                if a=="-a":
                    parsed["--auth"]=args[i+1]
                i+=1
            elif a=="-v":
                verbose+=1
                parsed["--verbose"]=verbose
            else:
                print(f"error: unexpected argument '{a}' found", file=sys.stderr)
                sys.exit(2)
        elif a.startswith("-"):
            # Could be -vvv etc?
            if set(a[1:]) <= set("vqb") or set(a[1:]) <= set("x"):
                # -vv counts
                for ch in a[1:]:
                    if ch=='v':
                        verbose+=1
                    elif ch=='q':
                        quiet+=1
                    elif ch=='x':
                        compress+=1
                parsed["--verbose"]=verbose
                parsed["--quiet"]=quiet
                parsed["--compress"]=compress
            else:
                # check unknown
                # For --pretty, --style etc with invalid value handled elsewhere
                # For unknown long option
                if a.startswith("--"):
                    # check if it's --pretty with invalid etc already handled? For other unknown
                    print(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
                    sys.exit(2)
                else:
                    print(f"error: unexpected argument '{a}' found", file=sys.stderr)
                    sys.exit(2)
        else:
            positional.append(a)
        i+=1

    # handle no-
    for k in list(parsed.keys()):
        if k.startswith("no-"):
            real="--"+k[3:]
            if real in parsed:
                del parsed[real]
            del parsed[k]

    default_scheme="http"
    if "--default-scheme" in parsed:
        default_scheme=parsed["--default-scheme"]
    elif "--https" in parsed:
        default_scheme="https"
    elif bin_name in ("xhs","https","xhttps"):
        default_scheme="https"

    if "--native-tls" in parsed:
        print(f"{bin_name}: error: This binary was built without native-tls support", file=sys.stderr)
        sys.exit(1)

    for pv in proxies:
        if ':' not in pv:
            print(f"error: invalid value '{pv}' for '--proxy <PROTOCOL:URL>': Invalid proxy URL '' for protocol '{pv}': relative URL without a base\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        proto,url_part = pv.split(':',1)
        try:
            p=urllib.parse.urlparse(url_part)
            if not p.scheme or not p.netloc:
                raise ValueError()
            if url_part.startswith('//'):
                raise ValueError()
        except:
            print(f"error: invalid value '{pv}' for '--proxy <PROTOCOL:URL>': Invalid proxy URL '{url_part}' for protocol '{proto}': relative URL without a base\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)

    if not positional:
        print(f"error: the following required arguments were not provided:\n  <[METHOD] URL>\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
        sys.exit(2)

    method=None
    url_str=None
    req_items=[]
    if len(positional)>=2:
        first=positional[0]
        second=positional[1]
        if is_method_token(first):
            try:
                u_str,parsed = parse_url_custom(second, default_scheme)
                method=first.upper()
                url_str=second
                req_items=positional[2:]
            except ValueError as e:
                if "invalid port" in str(e):
                    print(f"error: {e}", file=sys.stderr)
                    sys.exit(2)
                else:
                    url_str=first
                    req_items=positional[1:]
        else:
            url_str=first
            req_items=positional[1:]
    else:
        first=positional[0]
        try:
            u_str,parsed = parse_url_custom(first, default_scheme)
            url_str=first
        except ValueError as e:
            if "invalid port" in str(e):
                print(f"error: {e}", file=sys.stderr)
                sys.exit(2)
            else:
                print(f"error: Missing <URL>\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)

    try:
        url_final_str, url_parsed = parse_url_custom(url_str, default_scheme)
        final_url = urllib.parse.urlparse(url_final_str)
    except ValueError as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(2)

    items=[]
    for s in req_items:
        try:
            it=parse_request_item(s)
            items.append(it)
        except FileNotFoundError:
            print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
            sys.exit(1)
        except ValueError as e:
            msg=str(e)
            if "Invalid value" in msg:
                print(f"error: {msg}\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)
            else:
                print(f"error: {msg}", file=sys.stderr)
                sys.exit(2)

    body_type="json"
    for a in sys.argv:
        if a in ("--json","-j"):
            body_type="json"
        elif a in ("--form","-f"):
            body_type="form"
        elif a=="--multipart":
            body_type="multipart"

    has_data=False
    has_form_files=False
    has_body_file=False
    for it in items:
        if it[0] in ('data_field','data_field_file','json_field'):
            has_data=True
        elif it[0]=='form_file':
            if it[1]=='':
                has_body_file=True
            else:
                has_form_files=True
        elif it[0]=='body_file':
            has_body_file=True

    raw_opt_val = parsed.get("--raw")
    if raw_opt_val:
        if has_data or has_form_files:
            print(f"error: Request body (from --raw) and request data (key=value) cannot be mixed.\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        if has_body_file:
            print(f"error: Request body (from --raw) and request data (key=value) cannot be mixed.\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)

    if has_body_file and (has_data or has_form_files):
        print(f"{bin_name}: error: Request body (from a file) and request data (key=value) cannot be mixed.", file=sys.stderr)
        sys.exit(1)

    if body_type=="json" and has_form_files:
        print(f"{bin_name}: error: Can't use file fields in JSON mode (perhaps you meant --form?)", file=sys.stderr)
        sys.exit(1)

    stdin_content=None
    if not (parsed.get("--ignore-stdin") or parsed.get("-I")):
        if not sys.stdin.isatty():
            try:
                data=sys.stdin.read()
                stdin_content=data
            except:
                stdin_content=None

    if not (parsed.get("--ignore-stdin") or parsed.get("-I")) and not sys.stdin.isatty() and (has_data or has_form_files or has_body_file or raw_opt_val):
        print(f"{bin_name}: error: Request body (from stdin) and request data (key=value) cannot be mixed. Pass --ignore-stdin to ignore standard input.", file=sys.stderr)
        sys.exit(1)

    final_method = method if method else ("POST" if (has_data or has_form_files or has_body_file or raw_opt_val or stdin_content) else "GET")

    query_pairs=list(urllib.parse.parse_qsl(final_url.query))
    for it in items:
        if it[0]=='url_param':
            _,k,v = it
            query_pairs.append((k,v))
        elif it[0]=='url_param_file':
            _,k,fp = it
            try:
                content=open(fp,'r').read()
            except:
                print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                sys.exit(1)
            query_pairs.append((k, content.strip()))

    if query_pairs:
        q_str=urllib.parse.urlencode(query_pairs, doseq=True)
        final_url=final_url._replace(query=q_str)

    final_url_str=urllib.parse.urlunparse(final_url)
    path=final_url.path if final_url.path else "/"
    query=f"?{final_url.query}" if final_url.query else ""
    request_line=f"{final_method} {path}{query} HTTP/1.1"

    fmt_opts={}
    for fo in format_opts_list:
        for part in fo.split(','):
            if ':' in part:
                k,v=part.split(':',1)
                fmt_opts[k.strip()]=v.strip()

    pretty_val = parsed.get("--pretty")
    if not pretty_val:
        if not sys.stdout.isatty():
            pretty_val="none"
        else:
            if os.environ.get("NO_COLOR"):
                pretty_val="format"
            else:
                term=os.environ.get("TERM","")
                if term and term!="dumb":
                    pretty_val="all"
                else:
                    pretty_val="format"

    headers_sort=False
    if "headers.sort" in fmt_opts:
        headers_sort=fmt_opts["headers.sort"]=="true"
    else:
        headers_sort=pretty_val in ("format","all")

    json_format=False
    if "json.format" in fmt_opts:
        json_format=fmt_opts["json.format"]=="true"
    else:
        json_format=pretty_val in ("format","all")

    json_indent=4
    if "json.indent" in fmt_opts:
        try:
            json_indent=int(fmt_opts["json.indent"])
        except:
            pass

    body_str=None
    content_type=None
    is_multipart=False

    if raw_opt_val:
        body_str=raw_opt_val
        content_type="application/json"
    elif has_body_file:
        for it in items:
            if it[0]=='body_file':
                _,fn,ft = it
                ft=ft or guess_mime(fn)
                content_type=ft
                try:
                    body_str=open(fn,'r', errors='ignore').read()
                except:
                    print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                    sys.exit(1)
                break
            elif it[0]=='form_file':
                _,k,fn,ft,fnh = it
                if k=='':
                    ft=ft or guess_mime(fn)
                    content_type=ft
                    try:
                        body_str=open(fn,'r', errors='ignore').read()
                    except:
                        print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                        sys.exit(1)
                    break
    elif stdin_content is not None:
        body_str=stdin_content if stdin_content!='' else ""
        content_type="application/json"
    elif body_type=="json" and has_data:
        fields=[]
        for it in items:
            if it[0]=='data_field':
                _,k,rawk,v = it
                fields.append((rawk, v))
            elif it[0]=='data_field_file':
                _,k,rawk,fp = it
                try:
                    content=open(fp,'r').read()
                except:
                    print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                    sys.exit(1)
                fields.append((rawk, content))
            elif it[0]=='json_field':
                _,k,rawk,jv = it
                fields.append((rawk, jv))
        root={}
        for rawk,val in fields:
            insert_path(root, rawk, val)
        if json_format:
            if json_indent==2:
                body_str=json.dumps(root, indent=2)
            else:
                body_str=json.dumps(root, indent=4)
        else:
            body_str=json.dumps(root)
        content_type="application/json"
    elif body_type=="form":
        if has_form_files:
            is_multipart=True
            boundary=generate_boundary()
            content_type=f"multipart/form-data; boundary={boundary}"
            mp=[]
            for it in items:
                if it[0]=='data_field':
                    _,k,rawk,v = it
                    mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{v}\r\n")
                elif it[0]=='data_field_file':
                    _,k,rawk,fp = it
                    try:
                        content=open(fp,'r').read()
                    except:
                        print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                        sys.exit(1)
                    mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{content}\r\n")
                elif it[0]=='form_file':
                    _,k,fn,ft,fnh = it
                    if k=='':
                        continue
                    filename = fnh or os.path.basename(fn)
                    file_content = open(fn,'r', errors='ignore').read()
                    if ft:
                        mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"; filename=\"{filename}\"\r\nContent-Type: {ft}\r\n\r\n{file_content}\r\n")
                    else:
                        mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"; filename=\"{filename}\"\r\n\r\n{file_content}\r\n")
            mp.append(f"--{boundary}--\r\n")
            body_str=''.join(mp)
        else:
            pairs=[]
            for it in items:
                if it[0]=='data_field':
                    _,k,rawk,v = it
                    pairs.append((k,v))
                elif it[0]=='data_field_file':
                    _,k,rawk,fp = it
                    try:
                        content=open(fp,'r').read()
                    except:
                        print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                        sys.exit(1)
                    pairs.append((k, content.strip()))
                elif it[0]=='json_field':
                    _,k,rawk,jv = it
                    pairs.append((k, str(jv)))
            body_str=urllib.parse.urlencode(pairs, doseq=True)
            content_type="application/x-www-form-urlencoded"
    elif body_type=="multipart":
        is_multipart=True
        boundary=generate_boundary()
        content_type=f"multipart/form-data; boundary={boundary}"
        mp=[]
        for it in items:
            if it[0]=='data_field':
                _,k,rawk,v = it
                mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{v}\r\n")
            elif it[0]=='data_field_file':
                _,k,rawk,fp = it
                try:
                    content=open(fp,'r').read()
                except:
                    print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                    sys.exit(1)
                mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{content}\r\n")
            elif it[0]=='form_file':
                _,k,fn,ft,fnh = it
                if k=='':
                    continue
                filename = fnh or os.path.basename(fn)
                file_content = open(fn,'r', errors='ignore').read()
                if ft:
                    mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"; filename=\"{filename}\"\r\nContent-Type: {ft}\r\n\r\n{file_content}\r\n")
                else:
                    mp.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"; filename=\"{filename}\"\r\n\r\n{file_content}\r\n")
        mp.append(f"--{boundary}--\r\n")
        body_str=''.join(mp)

    custom_headers_ordered=[]
    headers_to_unset=[]
    has_content_encoding_custom=False
    for it in items:
        if it[0]=='header':
            _,k,v = it
            if not is_valid_header_name(k):
                print(f"{bin_name}: error: invalid HTTP header name", file=sys.stderr)
                sys.exit(1)
            if k.lower()=="content-encoding":
                has_content_encoding_custom=True
            custom_headers_ordered.append((k,v))
        elif it[0]=='header_file':
            _,k,fp = it
            if not is_valid_header_name(k):
                print(f"{bin_name}: error: invalid HTTP header name", file=sys.stderr)
                sys.exit(1)
            try:
                content=open(fp,'r').read()
            except:
                print(f"{bin_name}: error: No such file or directory (os error 2)", file=sys.stderr)
                sys.exit(1)
            if k.lower()=="content-encoding":
                has_content_encoding_custom=True
            custom_headers_ordered.append((k, content.strip()))
        elif it[0]=='header_unset':
            _,k = it
            headers_to_unset.append(k.lower())

    def find_last(name):
        lname=name.lower()
        for k,v in reversed(custom_headers_ordered):
            if k.lower()==lname:
                return v
        return None

    def has_custom_header(name):
        lname=name.lower()
        return any(k.lower()==lname for k,v in custom_headers_ordered)

    headers=[]
    accept_enc_default = "identity" if ("--download" in parsed or "-d" in parsed) else "gzip, deflate, br, zstd"
    user_agent_default = f"xh/{VERSION}"
    connection_default = "keep-alive"

    if "accept-encoding" not in headers_to_unset:
        v=find_last("accept-encoding")
        headers.append(("Accept-Encoding", v if v else accept_enc_default))
    if "user-agent" not in headers_to_unset:
        v=find_last("user-agent")
        headers.append(("User-Agent", v if v else user_agent_default))
    if "connection" not in headers_to_unset:
        v=find_last("connection")
        headers.append(("Connection", v if v else connection_default))

    auth_header=None
    bearer_val = parsed.get("--bearer")
    auth_val = parsed.get("--auth") or parsed.get("-a")
    auth_type_val = parsed.get("--auth-type") or parsed.get("-A")
    if bearer_val:
        auth_header=("Authorization", f"Bearer {bearer_val}")
    elif auth_val:
        at = auth_type_val if auth_type_val else "basic"
        if at=="bearer":
            auth_header=("Authorization", f"Bearer {auth_val}")
        elif at=="basic":
            enc=base64.b64encode(auth_val.encode()).decode()
            auth_header=("Authorization", f"Basic {enc}")

    is_get_like = not has_body and final_method=="GET"

    if is_get_like:
        if auth_header and "authorization" not in headers_to_unset and not has_custom_header("authorization"):
            headers.append(auth_header)
        remaining=[]
        for k,v in custom_headers_ordered:
            kl=k.lower()
            if kl in ("accept-encoding","user-agent","connection","authorization"):
                continue
            if kl in headers_to_unset:
                continue
            remaining.append((k,v))
        seen=set()
        dedup=[]
        for k,v in reversed(remaining):
            kl=k.lower()
            if kl in seen:
                continue
            seen.add(kl)
            dedup.append((k,v))
        dedup.reverse()
        headers.extend(dedup)

        if not has_custom_header("accept") and "accept" not in headers_to_unset:
            headers.append(("Accept","*/*"))
        if not has_custom_header("host") and "host" not in headers_to_unset:
            host = final_url.hostname or ""
            port = final_url.port
            host_h = f"{host}:{port}" if port else host
            headers.append(("Host", host_h))
    else:
        is_file_or_form = has_body_file or body_type in ("form","multipart")
        if is_file_or_form:
            if body_str is not None and "content-type" not in headers_to_unset:
                v=find_last("content-type")
                if v:
                    headers.append(("Content-Type", v))
                elif content_type:
                    headers.append(("Content-Type", content_type))
            if "accept" not in headers_to_unset:
                v=find_last("accept")
                if v:
                    headers.append(("Accept", v))
                else:
                    acc = "*/*" if body_type in ("form","multipart") or has_body_file else "application/json, */*;q=0.5"
                    headers.append(("Accept", acc))
        else:
            if "accept" not in headers_to_unset:
                v=find_last("accept")
                if v:
                    headers.append(("Accept", v))
                else:
                    acc = "*/*" if body_type in ("form","multipart") or has_body_file else "application/json, */*;q=0.5"
                    headers.append(("Accept", acc))
            if body_str is not None and "content-type" not in headers_to_unset:
                v=find_last("content-type")
                if v:
                    headers.append(("Content-Type", v))
                elif content_type:
                    headers.append(("Content-Type", content_type))

        if auth_header and "authorization" not in headers_to_unset and not has_custom_header("authorization"):
