                        parts.append("--data-binary")
                        parts.append(f"@{fn}")
            else:
                parts.append("--data" if "--curl-long" in sys.argv else "-d")
                parts.append(shell_quote(body_str))

        if parsed.get("--output"):
            parts.append("--output" if "--curl-long" in sys.argv else "-o")
