    if offline:
        out=""
        if 'H' in print_str:
            is_color = pretty_val in ("all","colors")
            if is_color:
                out+=f"\x1b[0m\x1b[32m{final_method}\x1b[0m \x1b[0m\x1b[4m\x1b[36m{path}{query}\x1b[0m \x1b[0m\x1b[34mHTTP\x1b[0m/\x1b[0m\x1b[34m1.1\x1b[0m\n"
