            else:
                out+=f"{request_line}\n"
                for k,v in headers:
                    out+=f"{k}: {v}\n"
            out+="\n"
        if 'B' in print_str:
            if body_str is not None:
                out+=body_str+"\n\n"
        sys.stdout.write(out)
        sys.exit(0)

    print(f"{bin_name}: error: Network requests not implemented, use --offline", file=sys.stderr)
    sys.exit(1)

if __name__=="__main__":
    main()
