                            cur_root=cur_root[-1][k]
                        else:
                            cur_root={k: [] if next_is_array else {}}
                    else:
                        cur_root={k: [] if next_is_array else {}}
        elif typ=='index':
            index=val
            if not isinstance(cur_root, list):
                # if cur_root is dict, this shouldn't happen, but we have already created list for key
                # So cur_root should be list
