            else:
                # check unknown
                # For --pretty, --style etc with invalid value handled elsewhere
                # For unknown long option
                if a.startswith("--"):
                    # check if it's --pretty with invalid etc already handled? For other unknown
                    print(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
