def parse_url_custom(inp, default_scheme):
    url_str=inp
    if url_str.startswith("://"):
        scheme=default_scheme if default_scheme else "http"
        url_str=f"{scheme}://{url_str[3:]}"
    elif url_str.startswith(":"):
        scheme=default_scheme if default_scheme else "http"
        if len(url_str)>=2 and url_str[1]=='/':
            url_str=f"{scheme}://localhost{url_str[1:]}"
        else:
            slash=url_str.find('/')
            if slash!=-1:
                port_part=url_str[:slash]
                path_part=url_str[slash:]
                url_str=f"{scheme}://localhost{port_part}{path_part}"
            else:
                url_str=f"{scheme}://localhost{url_str}"
    elif "://" not in url_str:
        scheme=default_scheme if default_scheme else "http"
        url_str=f"{scheme}://{url_str}"
    try:
        parsed=urllib.parse.urlparse(url_str)
        if not parsed.netloc:
            raise ValueError("invalid")
        netloc=parsed.netloc
        if ']' in netloc:
            if ']:' in netloc:
                port_part=netloc.split(']:',1)[1]
                if port_part and not port_part.split('/')[0].isdigit():
                    raise ValueError("invalid port number")
        else:
            if ':' in netloc:
                host_part=netloc.split('@')[-1]
                if ':' in host_part:
                    port_candidate=host_part.split(':')[-1]
                    port_candidate=port_candidate.split('/')[0].split('?')[0]
                    if port_candidate and not port_candidate.isdigit():
                        raise ValueError("invalid port number")
        return url_str, parsed
    except ValueError as e:
        if "invalid port" in str(e):
            raise ValueError("Invalid <URL>: invalid port number")
        raise ValueError(f"Invalid <URL>: {e}")
    except Exception as e:
        raise ValueError(f"Invalid <URL>: {e}")

def find_unescaped(s, pat):
    i=0
    while i+len(pat) <= len(s):
        if s[i]=='\\':
            i+=2
            continue
        if s[i:i+len(pat)]==pat:
            return i
        i+=1
    return -1

def unescape(s):
    res=[]
    i=0
    while i < len(s):
        if s[i]=='\\' and i+1 < len(s):
            res.append(s[i+1])
            i+=2
        else:
            res.append(s[i])
            i+=1
    return ''.join(res)

def parse_file_spec(spec):
    parts=spec.split(';')
    file_name=parts[0]
    ft=None
    fnh=None
    for part in parts[1:]:
        if part.startswith('type='):
            ft=part[5:]
        elif part.startswith('filename='):
            fnh=part[9:]
    return file_name, ft, fnh

def parse_request_item(item):
    if item.startswith('@'):
        rest=item[1:]
        fn,ft,_=parse_file_spec(rest)
        return ('body_file', fn, ft)
    pos=find_unescaped(item, '==')
    if pos!=-1:
        key=item[:pos]
        val=item[pos+2:]
        k=unescape(key)
        if val.startswith('@'):
            return ('url_param_file', k, val[1:])
        else:
            return ('url_param', k, unescape(val))
    pos=find_unescaped(item, ':=')
    if pos!=-1:
        key=item[:pos]
        val=item[pos+2:]
        raw_key=key
        k=unescape(key)
        if val.startswith('@'):
            try:
                content=open(val[1:],'r').read()
                j=json.loads(content)
            except FileNotFoundError:
                raise FileNotFoundError("No such file or directory (os error 2)")
            except Exception as e:
                raise ValueError(f"Invalid value for '[REQUEST_ITEM]...': {item!r} {e}")
            return ('json_field', k, raw_key, j)
        else:
            try:
                j=json.loads(val)
            except Exception:
                raise ValueError(f"Invalid value for '[REQUEST_ITEM]...': {item!r} expected value at line 1 column 1")
            return ('json_field', k, raw_key, j)
    pos=find_unescaped(item, '=')
    if pos!=-1:
        key=item[:pos]
        val=item[pos+1:]
        if val.startswith('@'):
            return ('data_field_file', unescape(key), key, val[1:])
        else:
            return ('data_field', unescape(key), key, unescape(val))
    pos=find_unescaped(item, '@')
    if pos!=-1 and pos>0:
        key=item[:pos]
        spec=item[pos+1:]
        fn,ft,fnh=parse_file_spec(spec)
        return ('form_file', unescape(key), fn, ft, fnh)
    pos=find_unescaped(item, ':')
    if pos!=-1:
        key=item[:pos]
        val=item[pos+1:]
        k=unescape(key)
        if val=='':
            return ('header_unset', k)
        if val.startswith('@'):
            return ('header_file', k, val[1:])
        return ('header', k, unescape(val))
    if item.endswith(';'):
        key=item[:-1]
        if key:
            return ('header', unescape(key), "")
